window.WORKSHOP_CODES = {
  "01_kamera.py": "\"\"\"01 - İlk kamera görüntüsü\n\nÖğrenme hedefi: Kamerayı açmak, kare okumak, ekranda göstermek ve kamerayı\ndüzgün kapatmak. Bu örnek yalnızca OpenCV kullanır; yardımcı modül yoktur.\n\nÇalıştırma : python examples/01_kamera.py\nKamerasız  : python examples/01_kamera.py --source video.mp4\nTuşlar     : f: Özellikler rehberi  |  q veya Esc: Çıkış\n\"\"\"\n\nimport argparse\nimport time\n\nimport cv2\n\nparser = argparse.ArgumentParser(description=\"İlk kamera görüntüsü\")\nparser.add_argument(\"--source\", default=\"0\", help=\"Kamera numarası (0, 1, ...) veya video dosyası\")\nparser.add_argument(\"--max-frames\", type=int, default=0, help=\"Otomatik test için kare sınırı\")\nargs = parser.parse_args()\nsource = int(args.source) if args.source.isdigit() else args.source\n\ndef kamera_ac(kaynak):\n    \"\"\"Kamerayı açar; Mac'te 0 numara (iPhone vb.) siyah/boş dönerse otomatik 1 numarayı dener.\"\"\"\n    import platform\n    backend = cv2.CAP_AVFOUNDATION if platform.system() == \"Darwin\" and isinstance(kaynak, int) else cv2.CAP_ANY\n    adaylar = [0, 1, 2] if kaynak == 0 else [kaynak]\n    yedek = None\n    for ad in adaylar:\n        c = cv2.VideoCapture(ad, backend) if isinstance(ad, int) else cv2.VideoCapture(ad)\n        if not c.isOpened():\n            c.release()\n            continue\n        for _ in range(25):\n            ok, test = c.read()\n            if ok and test is not None and test.size > 0:\n                if test.mean() >= 5.0 or not isinstance(ad, int):\n                    if yedek is not None:\n                        yedek.release()\n                    return c\n                if yedek is None:\n                    yedek = c\n                    c = None\n                    break\n            time.sleep(0.04)\n        if c is not None:\n            c.release()\n    return yedek\n\n\ncap = kamera_ac(source)\nif cap is None:\n    print(\"Kamera açılamadı veya görüntü gelmedi. Kamera iznini kontrol edin veya --source 1 deneyin.\")\n    raise SystemExit(1)\n\nWIN = \"VISION LAB - 01 Kamera (f: ozellikler | q: cikis)\"\nflags = cv2.WINDOW_NORMAL | (cv2.WINDOW_KEEPRATIO if hasattr(cv2, \"WINDOW_KEEPRATIO\") else 0)\ncv2.namedWindow(WIN, flags)\n\nframes = 0\nfps = 0.0\nshow_help = False\nsized = False\nlast = time.perf_counter()\ntry:\n    while True:\n        ok, frame = cap.read()             # ok: okuma başarılı mı, frame: NumPy dizisi\n        if not ok:\n            print(\"Kare okunamadı; kaynak bitti veya kamera bağlantısı kesildi.\")\n            break\n\n        if frames == 30 and frame.mean() < 5:\n            print(\"Görüntü siyah görünüyor. Mercek kapalı olabilir; başka kamera için: --source 1\")\n        frame = cv2.flip(frame, 1)         # 1: yatay çevirme, ayna görüntüsü\n        now = time.perf_counter()\n        fps = 0.9 * fps + 0.1 * (1.0 / max(now - last, 1e-6))   # yumuşatılmış FPS\n        last = now\n\n        height, width, channels = frame.shape\n        if not sized:\n            scale = min(1.0, 1120 / max(width, 1), 680 / max(height, 1))\n            cv2.resizeWindow(WIN, int(width * scale), int(height * scale))\n            sized = True\n\n        info = f\"{width}x{height}x{channels} {frame.dtype}  FPS: {fps:.1f}  |  [F] Ozellikler\"\n        cv2.rectangle(frame, (0, 0), (width, 40), (24, 18, 28), -1)\n        cv2.putText(frame, info, (12, 27), cv2.FONT_HERSHEY_SIMPLEX, 0.68, (191, 212, 45), 2, cv2.LINE_AA)\n\n        if show_help:\n            overlay = frame.copy()\n            cv2.rectangle(overlay, (width // 2 - 270, height // 2 - 90),\n                          (width // 2 + 270, height // 2 + 90), (24, 18, 28), -1)\n            cv2.addWeighted(overlay, 0.88, frame, 0.12, 0, frame)\n            cv2.rectangle(frame, (width // 2 - 270, height // 2 - 90),\n                          (width // 2 + 270, height // 2 + 90), (191, 212, 45), 2)\n            satirlar = [\n                \"01 - Ilk Kamera Goruntusu\",\n                \"Amac: Kamerayi acmak, NumPy kare boyutunu ve FPS'i gormek.\",\n                \"- Her kare (Yukseklik x Genislik x 3) uint8 dizisidir.\",\n                \"- [F] Bu pencereyi ac/kapat   |   [Q / Esc] Cikis\",\n            ]\n            for i, s in enumerate(satirlar):\n                cv2.putText(frame, s, (width // 2 - 250, height // 2 - 48 + i * 34),\n                            cv2.FONT_HERSHEY_SIMPLEX, 0.52, (233, 239, 242) if i else (191, 212, 45), 1, cv2.LINE_AA)\n\n        cv2.imshow(WIN, frame)\n\n        frames += 1\n        key = cv2.waitKey(1) & 0xFF        # 1 ms bekle; pencerenin çizilmesi için gerekli\n        if key in (ord(\"f\"), ord(\"F\")):\n            show_help = not show_help\n        elif key in (ord(\"q\"), 27) or (args.max_frames and frames >= args.max_frames):\n            break\nfinally:\n    cap.release()                          # kamerayı bırak: kamera ışığı sönmeli\n    cv2.destroyAllWindows()\n    print(f\"{frames} kare gösterildi. Kamera serbest bırakıldı.\")\n",
  "02_piksel_renk.py": "\"\"\"02 - Pikseller ve renk uzayları\n\nÖğrenme hedefi: Görüntünün bir NumPy dizisi olduğunu görmek; BGR-RGB farkını,\ngri tonlamayı, HSV ve LAB uzaylarını karşılaştırmak.\n\nÇalıştırma : python examples/02_piksel_renk.py\nKullanım   : Görüntüye tıklayın; o pikselin değerleri terminale yazılır.\n             b tuşu: \"BGR'yi RGB sanma\" hatasını aç/kapat.  q: çıkış\n\"\"\"\n\nimport _yol  # noqa: F401  (src klasörünü bulmak için)\n\nimport cv2\nimport numpy as np\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import DisplayLoop, build_parser\nfrom common.draw import put_text\nfrom common.frame import resize_to_width\n\nTILE_W = 320\n\n\ndef label(img, text):\n    put_text(img, text, (8, 6), 15, (233, 239, 242), bg=(31, 22, 15))\n    return img\n\n\ndef gray3(channel):\n    \"\"\"Tek kanallı görüntüyü yan yana koyabilmek için 3 kanala çevirir.\"\"\"\n    return cv2.cvtColor(channel, cv2.COLOR_GRAY2BGR)\n\n\ndef main():\n    args = build_parser(\"Pikseller ve renk uzayları\").parse_args()\n    state = {\"swap\": False, \"frame\": None}\n\n    def on_click(event, x, y, flags, param):\n        if event != cv2.EVENT_LBUTTONDOWN or state[\"frame\"] is None:\n            return\n        small = state[\"frame\"]\n        th = small.shape[0]\n        px, py = x % TILE_W, y % th              # hangi kutucuğa tıklanırsa aynı piksel\n        b, g, r = small[py, px]\n        h, s, v = cv2.cvtColor(small[py:py + 1, px:px + 1], cv2.COLOR_BGR2HSV)[0, 0]\n        L, a, bb = cv2.cvtColor(small[py:py + 1, px:px + 1], cv2.COLOR_BGR2LAB)[0, 0]\n        print(f\"piksel (x={px}, y={py})  BGR=({b},{g},{r})  RGB=({r},{g},{b})  \"\n              f\"HSV=({h},{s},{v})  LAB(8 bit)=({L},{a},{bb})  gri={int(0.114*b + 0.587*g + 0.299*r)}\")\n\n    try:\n        with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n                DisplayLoop(\n                    \"VISION LAB - 02 Piksel ve renk\",\n                    args,\n                    help_title=\"02 · Pikseller ve Renk Uzayları (BGR / HSV / LAB)\",\n                    help_lines=[\n                        \"Amaç: Aynı görüntünün BGR, Gri, HSV ve LAB renk uzaylarında nasıl göründüğünü kıyaslamak.\",\n                        \"• [Fare Tıklama] Herhangi bir piksele tıkla -> BGR, RGB, HSV, LAB değerleri terminale yazılır.\",\n                        \"• [b] BGR-RGB kanal tersliği (mavi-kırmızı yer değiştirme) hatasını aç/kapat.\",\n                        \"• [F] Bu rehberi aç/kapat  ·  [Q / Esc] Çıkış.\",\n                    ],\n                ) as loop:\n            loop.on_mouse(on_click)\n            first = cam.read()\n            print(f\"Kare: shape={first.shape} (yükseklik, genişlik, kanal), dtype={first.dtype}, \"\n                  f\"en küçük={first.min()}, en büyük={first.max()}\")\n            while loop.running:\n                frame = cam.read()\n                if frame is None:\n                    break\n                if not args.no_mirror:\n                    frame = cv2.flip(frame, 1)\n                small = resize_to_width(frame, TILE_W)\n                state[\"frame\"] = small\n\n                shown = small[:, :, ::-1].copy() if state[\"swap\"] else small.copy()   # kanalları ters çevir\n                gray = cv2.cvtColor(small, cv2.COLOR_BGR2GRAY)\n                hsv = cv2.cvtColor(small, cv2.COLOR_BGR2HSV)\n                lab = cv2.cvtColor(small, cv2.COLOR_BGR2LAB)\n\n                row1 = np.hstack([\n                    label(shown, \"RGB sanılan BGR (hatalı)\" if state[\"swap\"] else \"Orijinal (BGR)\"),\n                    label(gray3(gray), \"Gri ton\"),\n                    label(gray3(hsv[..., 0]), \"HSV: H (renk tonu)\"),\n                ])\n                row2 = np.hstack([\n                    label(gray3(hsv[..., 2]), \"HSV: V (parlaklık)\"),\n                    label(gray3(lab[..., 0]), \"LAB: L (açıklık)\"),\n                    label(gray3(lab[..., 1]), \"LAB: a (yeşil-kırmızı)\"),\n                ])\n                key = loop.show(np.vstack([row1, row2]))\n                if key == ord(\"b\"):\n                    state[\"swap\"] = not state[\"swap\"]\n    except CameraError as exc:\n        print(exc)\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "03_filtre_esik.py": "\"\"\"03 - ROI, bulanıklaştırma, eşikleme, morfoloji ve konturlar\n\nÖğrenme hedefi: Kural tabanlı bir görüntü işleme hattını adım adım kurmak ve\nher adımın süresini ölçmek.\n\nÇalıştırma : python examples/03_filtre_esik.py\nKullanım   : Pencerenin üstündeki sürgülerle parametreleri değiştirin.\n             Fareyle sürükleyerek ilgi bölgesini (ROI) seçin.  q: çıkış\n\"\"\"\n\nimport _yol  # noqa: F401\n\nimport cv2\nimport numpy as np\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import DisplayLoop, build_parser\nfrom common.draw import AMBER, TEAL, put_text\nfrom common.fps import FPSMeter, StageTimer\nfrom common.frame import resize_to_width\n\nWINDOW = \"VISION LAB - 03 Filtre ve esik\"\nTILE_W = 400\n\n\ndef odd(n: int) -> int:\n    \"\"\"Gaussian çekirdeği tek sayı olmalıdır: 0->1, 4->9 gibi.\"\"\"\n    return 2 * n + 1\n\n\ndef main():\n    args = build_parser(\"ROI, filtre, eşikleme ve konturlar\").parse_args()\n    roi = {\"rect\": None, \"start\": None}\n\n    def on_mouse(event, x, y, flags, param):\n        x = min(x, TILE_W - 1)                      # yalnızca ilk kutucukta seçim\n        if event == cv2.EVENT_LBUTTONDOWN:\n            roi[\"start\"] = (x, y)\n        elif event == cv2.EVENT_LBUTTONUP and roi[\"start\"]:\n            (x0, y0), (x1, y1) = roi[\"start\"], (x, y)\n            if abs(x1 - x0) > 10 and abs(y1 - y0) > 10:\n                roi[\"rect\"] = (min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1))\n            else:\n                roi[\"rect\"] = None                  # küçük tıklama seçimi sıfırlar\n            roi[\"start\"] = None\n\n    try:\n        with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n                DisplayLoop(\n                    WINDOW,\n                    args,\n                    help_title=\"03 · ROI, Gaussian Blur, Otsu Eşikleme & Konturlar\",\n                    help_lines=[\n                        \"Amaç: Kural tabanlı görüntü işleme hattını (bulanıklaştırma -> eşik -> morfoloji -> kontur) görmek.\",\n                        \"• [Fare ile Sürükle] Sol üst kutuda ilgi bölgesi (ROI) seç; küçük tıklama seçimi sıfırlar.\",\n                        \"• [Üst Sürgüler] blur, eşik (0 = otomatik Otsu) ve morfoloji boyutunu canlı değiştir.\",\n                        \"• [F] Bu rehberi aç/kapat  ·  [Q / Esc] Çıkış.\",\n                    ],\n                ) as loop:\n            loop.on_mouse(on_mouse)\n            cv2.createTrackbar(\"blur\", WINDOW, 2, 10, lambda v: None)\n            cv2.createTrackbar(\"esik (0=Otsu)\", WINDOW, 0, 255, lambda v: None)\n            cv2.createTrackbar(\"morfoloji\", WINDOW, 2, 10, lambda v: None)\n            timer, fps = StageTimer(), FPSMeter()\n\n            while loop.running:\n                frame = cam.read()\n                if frame is None:\n                    break\n                if not args.no_mirror:\n                    frame = cv2.flip(frame, 1)\n                with timer.measure(\"boyut\"):\n                    small = resize_to_width(frame, TILE_W)              # yeniden boyutlandırma\n                view = small.copy()\n                x1, y1, x2, y2 = roi[\"rect\"] or (0, 0, small.shape[1], small.shape[0])\n                region = small[y1:y2, x1:x2]                            # ROI: dizinin bir dilimi\n\n                k = odd(cv2.getTrackbarPos(\"blur\", WINDOW))\n                t = cv2.getTrackbarPos(\"esik (0=Otsu)\", WINDOW)\n                m = odd(cv2.getTrackbarPos(\"morfoloji\", WINDOW))\n                with timer.measure(\"gri+blur\"):\n                    gray = cv2.cvtColor(region, cv2.COLOR_BGR2GRAY)\n                    blurred = cv2.GaussianBlur(gray, (k, k), 0)\n                with timer.measure(\"eşik\"):\n                    if t == 0:   # Otsu, eşiği histogramdan otomatik seçer\n                        used, binary = cv2.threshold(blurred, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)\n                    else:\n                        used, binary = cv2.threshold(blurred, t, 255, cv2.THRESH_BINARY)\n                with timer.measure(\"morfoloji\"):\n                    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (m, m))\n                    opened = cv2.morphologyEx(binary, cv2.MORPH_OPEN, kernel)    # küçük lekeleri sil\n                    cleaned = cv2.morphologyEx(opened, cv2.MORPH_CLOSE, kernel)  # küçük delikleri kapat\n                with timer.measure(\"kontur\"):\n                    contours, _ = cv2.findContours(cleaned, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)\n                    big = [c for c in contours if cv2.contourArea(c) > 80]\n                    cv2.drawContours(view[y1:y2, x1:x2], big, -1, TEAL, 2)\n                cv2.rectangle(view, (x1, y1), (x2 - 1, y2 - 1), AMBER, 1)\n\n                def tile(img):\n                    out = np.zeros_like(small)\n                    out[y1:y2, x1:x2] = cv2.cvtColor(img, cv2.COLOR_GRAY2BGR)\n                    return out\n\n                t_blur, t_bin, t_clean = tile(blurred), tile(binary), tile(cleaned)\n                put_text(view, f\"ROI {x2 - x1}x{y2 - y1}  kontur: {len(big)}\", (8, 6), 15, bg=(31, 22, 15))\n                put_text(t_blur, f\"Gaussian {k}x{k}\", (8, 6), 15, bg=(31, 22, 15))\n                put_text(t_bin, f\"eşik = {used:.0f}\" + (\" (Otsu)\" if t == 0 else \"\"), (8, 6), 15, bg=(31, 22, 15))\n                put_text(t_clean, f\"açma + kapama {m}x{m}\", (8, 6), 15, bg=(31, 22, 15))\n                times = \"  \".join(f\"{name} {ms:.1f} ms\" for name, ms in timer.ms.items())\n                put_text(t_clean, f\"FPS {fps.tick():.0f}\", (8, t_clean.shape[0] - 26), 15, bg=(31, 22, 15))\n                grid = np.vstack([np.hstack([view, t_blur]), np.hstack([t_bin, t_clean])])\n                put_text(grid, times, (8, grid.shape[0] // 2 - 24), 14, bg=(31, 22, 15))\n                loop.show(grid)\n    except CameraError as exc:\n        print(exc)\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "04_yuz_tespiti.py": "\"\"\"04 - Yüz tespiti ve yüz işaret noktaları\n\nÖğrenme hedefi: Öğrenilmiş bir modelle (MediaPipe Face Landmarker) yüzü bulmak,\n478 noktayı ve yüz kutusunu çizmek, yüz yoksa uygun mesaj göstermek.\nKarşılaştırma için OpenCV'nin klasik Haar yöntemi de seçilebilir.\n\nÇalıştırma : python examples/04_yuz_tespiti.py\nHaar ile   : python examples/04_yuz_tespiti.py --yontem haar\nKullanım   : m tuşu: çizim biçimi (kontur / ağ / nokta)   q: çıkış\n\"\"\"\n\nimport _yol  # noqa: F401\n\nimport cv2\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import BLUE, put_text, status_line\nfrom common.fps import FPSMeter\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom face.overlay import draw_face\nfrom face.tracker import FaceTracker\n\nSTYLES = [\"kontur\", \"ag\", \"nokta\"]\n\n\ndef run_haar(args):\n    \"\"\"Klasik yöntem: Viola-Jones (Haar) sınıflandırıcısı. Yalnızca kutu verir, nokta vermez.\"\"\"\n    cascade = cv2.CascadeClassifier(cv2.data.haarcascades + \"haarcascade_frontalface_default.xml\")\n    prepare, fps = FramePreparer(config.PROCESS_WIDTH), FPSMeter()\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            DisplayLoop(\"VISION LAB - 04 Yuz (Haar)\", args) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            gray = cv2.cvtColor(frame.bgr, cv2.COLOR_BGR2GRAY)\n            boxes = cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(60, 60))\n            canvas = Canvas(frame, mirror=not args.no_mirror)\n            for (x, y, w, h) in boxes:\n                p1, p2 = canvas.pts([x, y]), canvas.pts([x + w, y + h])\n                cv2.rectangle(canvas.image, (int(p1[0]), int(p1[1])), (int(p2[0]), int(p2[1])), BLUE, 2)\n            canvas.flip()\n            put_text(canvas.image, f\"Haar: {len(boxes)} yüz  FPS {fps.tick():.0f}\", (12, 10), 18, bg=(31, 22, 15))\n            loop.show(canvas.image)\n\n\ndef main():\n    parser = build_parser(\"Yüz tespiti ve işaret noktaları\")\n    parser.add_argument(\"--yontem\", choices=[\"mediapipe\", \"haar\"], default=\"mediapipe\")\n    parser.add_argument(\"--max-faces\", type=int, default=config.MAX_FACES)\n    args = parser.parse_args()\n    if args.yontem == \"haar\":\n        run_haar(args)\n        return\n\n    style = 0\n    prepare, fps = FramePreparer(config.PROCESS_WIDTH), FPSMeter()\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            FaceTracker(max_faces=args.max_faces) as faces, \\\n            DisplayLoop(\n                \"VISION LAB - 04 Yuz noktalari\",\n                args,\n                help_title=\"04 · Yüz Tespiti & 478 Yüz İşaret Noktası\",\n                help_lines=[\n                    \"Amaç: MediaPipe Face Landmarker ile yüzü bulmak ve 478 noktayı gerçek zamanlı çizmek.\",\n                    \"• [m] Çizim stilini değiştirir: kontur -> 478 nokta ağı -> yalnızca noktalar.\",\n                    \"• Klasik Haar yöntemiyle kıyaslamak için: --yontem haar parametresiyle çalıştır.\",\n                    \"• [F] Bu rehberi aç/kapat  ·  [Q / Esc] Çıkış.\",\n                ],\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)                     # tek kare hazırlığı: boyut, RGB, mp.Image\n            result = faces.process(frame)            # model çağrısı\n\n            canvas = Canvas(frame, mirror=not args.no_mirror)\n            for face in result.faces:                # 1) şekiller\n                draw_face(canvas.image, canvas.pts(face.points), canvas.pts(face.box), STYLES[style])\n            canvas.flip()                            # 2) ayna\n            for face in result.faces:                # 3) yazılar\n                x1 = canvas.screen((face.box[2] if canvas.mirror else face.box[0], face.box[1]))\n                put_text(canvas.image, f\"iz {face.track_id}\", (int(x1[0]), int(x1[1]) - 26), 16, bg=(31, 22, 15))\n            n_points = len(result.faces[0].points) if result.faces else 0\n            put_text(canvas.image, f\"{n_points} nokta  model {result.latency_ms:.1f} ms  FPS {fps.tick():.0f}\",\n                     (12, 10), 18, bg=(31, 22, 15))\n            status_line(canvas.image, result.status, \"ok\" if result.faces else \"warn\")\n            if loop.show(canvas.image) == ord(\"m\"):\n                style = (style + 1) % len(STYLES)\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "05_yuz_takip.py": "\"\"\"05 - Yüz takibi, hareket izi ve titreme azaltma\n\nÖğrenme hedefi: Yüz merkezinin hareketini izlemek; ham iz ile yumuşatılmış izi\nkarşılaştırmak; takip numarasının kimlik olmadığını görmek.\n\nÇalıştırma : python examples/05_yuz_takip.py\nİki yüz    : python examples/05_yuz_takip.py --max-faces 2\nKullanım   : + / - : yumuşatma katsayısı (alpha)   c: izi temizle   q: çıkış\n\"\"\"\n\nimport _yol  # noqa: F401\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import GRAY, TEAL, put_text, status_line\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom face.overlay import draw_face, draw_trails\nfrom face.tracker import FaceTracker\n\n\ndef main():\n    parser = build_parser(\"Yüz takibi ve hareket izi\")\n    parser.add_argument(\"--max-faces\", type=int, default=config.MAX_FACES)\n    args = parser.parse_args()\n    alpha = config.EMA_ALPHA\n    prepare = FramePreparer(config.PROCESS_WIDTH)\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            FaceTracker(max_faces=args.max_faces, ema_alpha=alpha) as faces, \\\n            DisplayLoop(\n                \"VISION LAB - 05 Yuz takibi\",\n                args,\n                help_title=\"05 · Yüz Takibi & EMA Titreme Azaltma\",\n                help_lines=[\n                    \"Amaç: Yüz merkezinin ham hareket izini (gri) EMA yumuşatılmış iz (turkuaz) ile kıyaslamak.\",\n                    \"• [+ / -] Yumuşatma katsayısını (alpha) artırıp azalt: düşük alpha daha yumuşak ama gecikmeli.\",\n                    \"• [c] Ekrandaki hareket izini temizler.\",\n                    \"• [F] Bu rehberi aç/kapat  ·  [Q / Esc] Çıkış.\",\n                ],\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            result = faces.process(frame)\n\n            canvas = Canvas(frame, mirror=not args.no_mirror)\n            for face in result.faces:\n                draw_face(canvas.image, canvas.pts(face.points), None, \"nokta\")\n                raw_trail, smooth_trail = faces.trails(face.track_id)\n                draw_trails(canvas.image, raw_trail, smooth_trail, canvas.scale)\n            canvas.flip()\n            for face in result.faces:\n                x, y = canvas.screen(face.center_smooth)\n                put_text(canvas.image, f\"iz {face.track_id}\", (int(x) + 10, int(y) - 30), 16, bg=(31, 22, 15))\n            put_text(canvas.image, \"gri: ham merkez   turkuaz: yumuşatılmış merkez\", (12, 10), 16, GRAY,\n                     bg=(31, 22, 15))\n            put_text(canvas.image, f\"alpha = {alpha:.2f}  (+/- ile değiştir)\", (12, 38), 16, TEAL, bg=(31, 22, 15))\n            status_line(canvas.image, result.status, \"ok\" if result.faces else \"warn\")\n\n            key = loop.show(canvas.image)\n            if key in (ord(\"+\"), ord(\"=\")):\n                alpha = min(1.0, alpha + 0.05)\n            elif key == ord(\"-\"):\n                alpha = max(0.05, alpha - 0.05)\n            elif key == ord(\"c\"):\n                faces.clear_trails()\n            if key in (ord(\"+\"), ord(\"=\"), ord(\"-\")):\n                faces.set_smoothing(alpha)\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "06_yuz_geometrisi.py": "\"\"\"06 - Yüz geometrisi ve hareket analizi\n\nÖğrenme hedefi: Noktalardan normalize ölçümler üretmek: göz ve ağız açıklığı,\nyaklaşık baş yönelimi ve yüz oranları. Kural tabanlı ölçümü (EAR) modelin\nöğrenilmiş çıktısıyla (blendshape) karşılaştırmak.\n\nÇalıştırma : python examples/06_yuz_geometrisi.py\nKullanım   : q: çıkış\n\nNot: Bu ölçümler gözlenebilir hareketlerdir. Kişilik, zekâ, güvenilirlik veya\nduygu durumu hakkında bilgi vermez.\n\"\"\"\n\nimport _yol  # noqa: F401\n\nfrom collections import deque\n\nimport numpy as np\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import AMBER, GRAY, TEAL, WHITE, panel, put_text, status_line\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom face.metrics import (LEFT_EYE_EAR, RIGHT_EYE_EAR, BlinkDetector, approximate_shape_tendency,\n                          eye_aspect_ratio, face_ratios, is_frontal, mouth_aspect_ratio)\nfrom face.overlay import draw_face\nfrom face.tracker import FaceTracker\n\n\ndef shape_status(face, frame_width, history) -> tuple[str, str]:\n    \"\"\"Şekil eğilimi yalnızca uygun koşullarda gösterilir; aksi halde neden yazılır.\"\"\"\n    if not is_frontal(face.pose):\n        history.clear()\n        return \"Uygun görüntü bekleniyor: başınızı düz tutup kameraya bakın.\", \"warn\"\n    if face.width_px / frame_width < config.MIN_FACE_WIDTH_RATIO:\n        history.clear()\n        return \"Uygun görüntü bekleniyor: kameraya biraz yaklaşın.\", \"warn\"\n    ratios = face_ratios(face.points)\n    history.append(ratios[\"uzunluk/genişlik\"])\n    if len(history) < config.SHAPE_STABLE_FRAMES or np.std(history) > config.SHAPE_MAX_RATIO_STD:\n        return \"Uygun görüntü bekleniyor: birkaç saniye hareketsiz kalın.\", \"warn\"\n    return f\"Yaklaşık: {approximate_shape_tendency(ratios)} (standart bir sınıf değildir)\", \"ok\"\n\n\ndef main():\n    args = build_parser(\"Yüz geometrisi ve hareket analizi\").parse_args()\n    prepare = FramePreparer(config.PROCESS_WIDTH)\n    blink = BlinkDetector()\n    history: deque = deque(maxlen=config.SHAPE_STABLE_FRAMES)\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            FaceTracker(blendshapes=True) as faces, \\\n            DisplayLoop(\n                \"VISION LAB - 06 Yuz geometrisi\",\n                args,\n                help_title=\"06 · Yüz Geometrisi, EAR Göz Kırpma & Baş Pozu\",\n                help_lines=[\n                    \"Amaç: 478 noktadan mesafeden bağımsız göz kırpma (EAR), ağız açıklığı ve baş yönelimi ölçmek.\",\n                    \"• Göz kırptığında EAR düşer ve göz kırpma sayacı artar; sağ panelde blendshape ile kıyasla.\",\n                    \"• Başını sağa/sola çevirerek dönüş (yaw), eğim (pitch) ve yatma (roll) açılarını incele.\",\n                    \"• [F] Bu rehberi aç/kapat  ·  [Q / Esc] Çıkış.\",\n                ],\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            result = faces.process(frame)\n            canvas = Canvas(frame, mirror=not args.no_mirror)\n            if result.faces:\n                draw_face(canvas.image, canvas.pts(result.faces[0].points), None, \"kontur\")\n            canvas.flip()\n\n            img = canvas.image\n            x0 = canvas.width - 360\n            panel(img, x0, 0, canvas.width, canvas.height - 38)\n            put_text(img, \"Yüz geometrisi\", (x0 + 14, 12), 18, WHITE)\n            if not result.faces:\n                blink.reset()\n                history.clear()\n                status_line(img, result.status, \"warn\")\n                loop.show(img)\n                continue\n\n            face = result.faces[0]\n            p = face.points\n            ear = (eye_aspect_ratio(p, RIGHT_EYE_EAR) + eye_aspect_ratio(p, LEFT_EYE_EAR)) / 2\n            closed = blink.update(ear)\n            mar = mouth_aspect_ratio(p)\n            bs = face.blendshapes\n            rows = [\n                (\"Kural tabanlı (geometri)\", None, TEAL),\n                (f\"göz açıklığı EAR {ear:.2f}\", \"kapalı\" if closed else \"açık\", WHITE),\n                (f\"göz kırpma sayısı {blink.blinks}\", None, WHITE),\n                (f\"ağız açıklığı {mar:.2f}\", \"açık\" if mar > config.MOUTH_OPEN_MAR else \"kapalı\", WHITE),\n                (\"Öğrenilmiş (blendshape, 0-1)\", None, TEAL),\n                (f\"eyeBlinkLeft {bs.get('eyeBlinkLeft', 0):.2f}  Right {bs.get('eyeBlinkRight', 0):.2f}\", None, WHITE),\n                (f\"jawOpen {bs.get('jawOpen', 0):.2f}\", None, WHITE),\n                (\"Yaklaşık baş yönelimi (derece)\", None, TEAL),\n            ]\n            if face.pose:\n                rows.append((f\"dönüş {face.pose.yaw:+.0f}  eğim {face.pose.pitch:+.0f}  \"\n                             f\"yatma {face.pose.roll:+.0f}\", None, WHITE))\n            rows.append((\"Oranlar (yüz genişliğine göre)\", None, TEAL))\n            for name, value in face_ratios(p).items():\n                rows.append((f\"{name} {value:.2f}\", None, WHITE))\n            y = 44\n            for text, tag, color in rows:\n                if y > canvas.height - 84:\n                    break\n                put_text(img, text, (x0 + 14, y), 14, color)\n                if tag:\n                    put_text(img, tag, (x0 + 270, y), 14, AMBER)\n                y += 22\n            if y + 24 < canvas.height - 42:\n                put_text(img, \"Ölçümler hareket bilgisidir; duygu\", (x0 + 14, y + 6), 12, GRAY)\n                put_text(img, \"veya kişilik çıkarımı yapılmaz.\", (x0 + 14, y + 22), 12, GRAY)\n\n            message, kind = shape_status(face, frame.size[0], history)\n            status_line(img, message, kind)\n            loop.show(img)\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "07_el_noktalari.py": "\"\"\"07 - El işaret noktaları ve parmak durumları\n\nÖğrenme hedefi: 21 el noktasını görmek, eklem açılarından parmakların açık mı\nkapalı mı olduğunu belirlemek ve sağ/sol etiketini bir deneyle kontrol etmek.\n\nÇalıştırma : python examples/07_el_noktalari.py\nKullanım   : n: nokta numaralarını göster/gizle   q: çıkış\n\nDeney: Yalnızca SAĞ elinizi kaldırın. Ekranda \"sağ\" yazmalı. \"sol\" yazıyorsa\nsrc/config.py içinde HANDEDNESS_SWAP = True yapın ve tekrar deneyin.\n\"\"\"\n\nimport _yol  # noqa: F401\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import AMBER, GRAY, TEAL, WHITE, panel, put_text, status_line\nfrom common.frame import FramePreparer\nfrom common.geometry import angle_deg\nfrom common.models import ModelMissingError\nfrom hands.gestures import FINGERS, GESTURE_NAMES, classify_static, finger_states\nfrom hands.overlay import draw_hand\nfrom hands.tracker import HandTracker\n\n\ndef main():\n    parser = build_parser(\"El işaret noktaları ve parmak durumları\")\n    parser.add_argument(\"--max-hands\", type=int, default=2)\n    args = parser.parse_args()\n    prepare = FramePreparer(config.PROCESS_WIDTH)\n    show_ids = False\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            HandTracker(max_hands=args.max_hands) as hands, \\\n            DisplayLoop(\n                \"VISION LAB - 07 El noktalari\",\n                args,\n                help_title=\"07 · 21 El Eklem Noktası & Parmak Açıları\",\n                help_lines=[\n                    \"Amaç: 21 el noktasından parmak eklem açılarını hesaplayıp açık/kapalı durumlarını görmek.\",\n                    \"• [n] 0–20 arası eklem noktalarının numaralarını el üzerinde göster/gizle.\",\n                    \"• Deney: Yalnızca SAĞ elini kaldır; etiket 'sağ' yazmalı (sol yazarsa config.py HANDEDNESS_SWAP).\",\n                    \"• [F] Bu rehberi aç/kapat  ·  [Q / Esc] Çıkış.\",\n                ],\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            result = hands.process(frame)\n            canvas = Canvas(frame, mirror=not args.no_mirror)\n            for hand in result.hands:\n                draw_hand(canvas.image, canvas.pts(hand.points))\n            canvas.flip()\n            img = canvas.image\n\n            for k, hand in enumerate(result.hands):\n                wx, wy = canvas.screen(hand.points[0])\n                put_text(img, f\"{hand.label_tr} el ({hand.score:.2f})\", (int(wx) - 40, int(wy) + 12), 16,\n                         bg=(31, 22, 15))\n                if show_ids:\n                    for i, pt in enumerate(hand.points):\n                        x, y = canvas.screen(pt)\n                        put_text(img, str(i), (int(x) + 4, int(y) - 14), 11, AMBER)\n                states = finger_states(hand.points)\n                x0, y0 = 12 + k * 300, 12\n                panel(img, x0, y0, x0 + 290, y0 + 176)\n                put_text(img, f\"{hand.label_tr} el: {GESTURE_NAMES[classify_static(states)]}\", (x0 + 10, y0 + 8), 16, TEAL)\n                for j, (name, (a, b, c, d)) in enumerate(FINGERS.items()):\n                    angle = angle_deg(hand.points[a], hand.points[b], hand.points[c])\n                    state = {True: \"açık\", False: \"kapalı\", None: \"belirsiz\"}[states[name]]\n                    put_text(img, f\"{name:<10} {angle:5.0f}°  {state}\", (x0 + 10, y0 + 36 + 26 * j), 15,\n                             WHITE if states[name] is not None else GRAY)\n            status_line(img, result.status + \"   Deney: sağ elinizi kaldırın, etiket 'sağ' olmalı.\",\n                        \"ok\" if result.hands else \"warn\")\n            if loop.show(img) == ord(\"n\"):\n                show_ids = not show_ids\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "08_el_jestleri.py": "\"\"\"08 - Kararlı jestler, Neon Hava Çizimi (isim yazma), 1-5 parmakla renk değişimi & yumrukla silme\n\nÖğrenme hedefi:\n  • İşaret parmağıyla havada parlayan NEON karalama ve isim yazma\n  • 100% temassız renk seçimi: 👍 Başparmak -> 1:Turkuaz | 2-5 Parmak -> Sarı, Pembe, Yeşil, Mavi\n  • Yumruk (0 parmak, 0.7 sn tut) hareketiyle tüm ekranı silme\n  • Pinch (başparmak + işaret) ile fırça kalınlığı sürgüsünü ve kutuyu taşıma\n  • 'n' Neon Parıltı aç/kapat | 'z' Geri Al (Undo) | 's' PNG kaydet | 'f' Özellikler rehberi\n\nÇalıştırma : python examples/08_el_jestleri.py\nTuşlar     : f: Özellikler | n: Neon Glow | z: Geri Al | 1-5: Hızlı renk | s: PNG | c: Temizle | q: Çıkış\n\"\"\"\n\nimport _yol  # noqa: F401\n\nimport time\nfrom collections import deque\n\nimport cv2\nimport numpy as np\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import AMBER, GRAY, INK, TEAL, WHITE, panel, put_text, status_line\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom hands.gestures import GESTURE_NAMES, GestureController, finger_states\nfrom hands.overlay import draw_hand, draw_pinch_gauge\nfrom hands.tracker import HandTracker\nfrom hands.widgets import DraggableBox, DrawingCanvas, Slider\n\n# 5 renkli palet: (BGR renk, Türkçe ad)\nPALET = [\n    ((191, 212, 45), \"1: Turkuaz\"),\n    ((60, 215, 255), \"2: Altın Sarı\"),\n    ((180, 95, 255), \"3: Neon Pembe\"),\n    ((140, 235, 110), \"4: Mint Yeşil\"),\n    ((255, 150, 65), \"5: Elektrik Mavi\"),\n]\n\nHELP_LINES = [\n    \"Amaç: İşaret parmağınla havada parlayan NEON yazı yazmak ve renk seçmek.\",\n    \"• ÇİZİM: Sadece İŞARET parmağını kaldırıp havada hareket ettir -> ekrana yazar!\",\n    \"• EN KOLAY RENK SEÇİMİ: Parmağını üstteki 5 renk kutusundan birinin üzerine götür!\",\n    \"• PARMAKLA RENK: Kameraya 2 (Sarı), 3 (Pembe), 4 (Yeşil) veya 5 parmak (Mavi) göster.\",\n    \"• SİLME: Elini YUMRUK yapıp 0.7 saniye tut -> tüm çizim silinir.\",\n    \"• KISAYOLLAR: [1-5] Renk · [n] Neon aç/kapat · [z] Geri Al · [s] PNG kaydet · [F] Kapat\",\n]\n\n\ndef acik_parmak_sayisi(points) -> tuple[int, dict]:\n    \"\"\"Açık (True) olan parmak sayısını (0-5) ve sözlüğünü döndürür.\"\"\"\n    states = finger_states(points)\n    return sum(1 for v in states.values() if v is True), states\n\n\ndef neon_cizim_birlestir(img: np.ndarray, layer: np.ndarray, neon_on: bool) -> None:\n    \"\"\"Çizim katmanını hızlı 1/4 ölçekli Gaussian Neon Bloom parıltısıyla görüntüye ekler.\"\"\"\n    if neon_on:\n        h, w = layer.shape[:2]\n        kucuk = cv2.resize(layer, (max(1, w // 4), max(1, h // 4)), interpolation=cv2.INTER_LINEAR)\n        glow = cv2.resize(cv2.GaussianBlur(kucuk, (11, 11), 0), (w, h), interpolation=cv2.INTER_LINEAR)\n        cv2.add(img, glow, dst=img)\n    cv2.add(img, layer, dst=img)\n\n\ndef palet_kutulari(w: int) -> list[tuple[int, int, int, int]]:\n    \"\"\"Üstteki 5 renk kutusunun ekran koordinatlarını (x1, y1, x2, y2) döndürür.\"\"\"\n    kutu_w, kutu_h, gap = 116, 38, 8\n    toplam_w = len(PALET) * kutu_w + (len(PALET) - 1) * gap\n    x0 = max(12, (w - toplam_w) // 2)\n    y0 = 10\n    return [(x0 + i * (kutu_w + gap), y0, x0 + i * (kutu_w + gap) + kutu_w, y0 + kutu_h)\n            for i in range(len(PALET))]\n\n\ndef palet_ciz(img, aktif_idx: int, parmak_sayisi: int | None, neon_on: bool) -> list[tuple[int, int, int, int]]:\n    \"\"\"Üst ortaya dokunmatik 5 renkli canlı palet çubuğunu çizer.\"\"\"\n    kutular = palet_kutulari(img.shape[1])\n    x0, y0 = kutular[0][0], kutular[0][1]\n    x_son, y_son = kutular[-1][2], kutular[-1][3]\n    panel(img, x0 - 8, y0 - 5, x_son + 8, y_son + 6, alpha=0.82)\n    for i, ((rx1, ry1, rx2, ry2), (bgr, ad)) in enumerate(zip(kutular, PALET)):\n        cv2.rectangle(img, (rx1, ry1), (rx2, ry2), bgr, -1)\n        if i == aktif_idx:\n            cv2.rectangle(img, (rx1 - 2, ry1 - 2), (rx2 + 2, ry2 + 2), WHITE, 3, cv2.LINE_AA)\n        put_text(img, ad, (rx1 + 7, ry1 + 10), 13, INK)\n    info = f\"Renk seçmek için parmağını kutuya değdir!  ·  Neon: {'AÇIK' if neon_on else 'KAPALI'} [n]\"\n    put_text(img, info, (x0, y_son + 10), 13, TEAL, bg=INK)\n    return kutular\n\n\ndef main():\n    args = build_parser(\"Kararlı jestler, Neon hava çizimi ve renk paleti\").parse_args()\n    prepare = FramePreparer(config.PROCESS_WIDTH)\n    controller = GestureController()\n    log: deque = deque(maxlen=4)\n    undo_stack: deque = deque(maxlen=15)\n    widgets = None\n\n    aktif_renk_idx = 0\n    neon_on = True\n    onceki_ciziyor = False\n    fist_since = None\n    color_hold_target = None\n    color_hold_since = None\n    son_bildirim = \"\"\n    bildirim_bitis = 0.0\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            HandTracker(max_hands=1) as hands, \\\n            DisplayLoop(\n                \"VISION LAB - 08 Neon Hava Cizimi & El Jestleri\",\n                args,\n                help_title=\"08 · Neon Hava Çizimi, 1–5 Parmak Renk & Yumrukla Sil\",\n                help_lines=HELP_LINES,\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            result = hands.process(frame)\n            canvas = Canvas(frame, mirror=not args.no_mirror)\n            if widgets is None:\n                w, h = canvas.width, canvas.height\n                widgets = (\n                    Slider(56, h - 72, min(320, w // 3), \"fırça kalınlığı\", value=0.35),\n                    DraggableBox(w - 140, 120, size=86),\n                    DrawingCanvas(w, h),\n                )\n            slider, box, drawing = widgets\n\n            hand = result.hands[0] if result.hands else None\n            cursor = canvas.screen(hand.points[8]) if hand else None\n            state = controller.update(hand.points if hand else None, frame.timestamp_ms, cursor)\n            started = \"pinch_basladi\" in state.events\n            for event in state.events:\n                log.appendleft(f\"{frame.timestamp_ms / 1000:5.1f}s {event}\")\n\n            slider.update(cursor, started, state.pinching)\n            box.update(cursor, started, state.pinching and not slider.dragging)\n            firca_kalinlik = int(3 + slider.value * 13)\n\n            parmak_n, fstates = acik_parmak_sayisi(hand.points) if hand else (None, {})\n            now_ms = frame.timestamp_ms\n            kutular = palet_kutulari(canvas.width)\n\n            # Üstteki renk kutularına parmak değdi mi? (En kolay & anında renk seçimi!)\n            palet_uzerinde = False\n            if cursor is not None:\n                cx_p, cy_p = cursor\n                if cy_p <= 64:\n                    palet_uzerinde = True\n                for idx_k, (rx1, ry1, rx2, ry2) in enumerate(kutular):\n                    if rx1 <= cx_p <= rx2 and ry1 - 6 <= cy_p <= ry2 + 10:\n                        if aktif_renk_idx != idx_k:\n                            aktif_renk_idx = idx_k\n                            son_bildirim = f\"Renk seçildi -> {PALET[aktif_renk_idx][1]}\"\n                            bildirim_bitis = time.monotonic() + 1.5\n                        break\n\n            # 1) İşaret parmağıyla havada çizim / isim yazma (üst palet bölgesinde çizmez)\n            ciziyor = (hand is not None and state.gesture == \"isaret\"\n                       and not state.pinching and not palet_uzerinde)\n            if ciziyor and not onceki_ciziyor:\n                undo_stack.append(drawing.layer.copy())\n            onceki_ciziyor = ciziyor\n\n            renk_bgr, renk_ad = PALET[aktif_renk_idx]\n            drawing.update(cursor, ciziyor, color=renk_bgr, thickness=firca_kalinlik)\n\n            # 2) %100 temassız renk seçimi: 👍 sadece başparmak -> 1:Turkuaz | 2-5 parmak -> 2..5\n            hedef_renk = None\n            if hand is not None and not state.pinching:\n                sadece_basparmak = (parmak_n == 1 and fstates.get(\"başparmak\") is True)\n                if sadece_basparmak:\n                    hedef_renk = 0\n                elif parmak_n in (2, 3, 4, 5):\n                    hedef_renk = parmak_n - 1\n\n            if hedef_renk is not None:\n                if color_hold_target != hedef_renk:\n                    color_hold_target = hedef_renk\n                    color_hold_since = now_ms\n                elif now_ms - color_hold_since >= 350 and aktif_renk_idx != hedef_renk:\n                    aktif_renk_idx = hedef_renk\n                    son_bildirim = f\"Renk değişti -> {PALET[aktif_renk_idx][1]}\"\n                    bildirim_bitis = time.monotonic() + 1.8\n                    log.appendleft(f\"{now_ms / 1000:5.1f}s renk: {PALET[aktif_renk_idx][1]}\")\n            else:\n                color_hold_target = None\n                color_hold_since = None\n\n            # 3) Yumruk (0 parmak) ile 0.7 sn tutunca ekranı silme\n            silme_orani = 0.0\n            if hand is not None and (state.gesture == \"yumruk\" or parmak_n == 0) and not state.pinching:\n                fist_since = fist_since or now_ms\n                silme_orani = min(1.0, (now_ms - fist_since) / 700.0)\n                if silme_orani >= 1.0:\n                    undo_stack.append(drawing.layer.copy())\n                    drawing.clear()\n                    son_bildirim = \"Yumruk algılandı -> Tüm çizim silindi! (z: geri al)\"\n                    bildirim_bitis = time.monotonic() + 2.0\n                    log.appendleft(f\"{now_ms / 1000:5.1f}s yumruk: çizim silindi\")\n                    fist_since = None\n                    silme_orani = 0.0\n            else:\n                fist_since = None\n\n            if hand:\n                draw_hand(canvas.image, canvas.pts(hand.points), highlight_pinch=state.pinching)\n            canvas.flip()\n            img = canvas.image\n            neon_cizim_birlestir(img, drawing.layer, neon_on)\n            slider.draw(img)\n            box.draw(img)\n\n            # İşaret parmağı ucunda her zaman görünür imleç halkası\n            if cursor is not None:\n                cv2.circle(img, (int(cursor[0]), int(cursor[1])),\n                           max(7, firca_kalinlik) if ciziyor else 6, renk_bgr, 2, cv2.LINE_AA)\n\n            # Üst renk paleti\n            palet_ciz(img, aktif_renk_idx, parmak_n, neon_on)\n\n            # Sol kompakt durum kartı\n            panel(img, 12, 62, 268, 212, alpha=0.76)\n            put_text(img, f\"Jest: {GESTURE_NAMES[state.gesture]}\", (22, 70), 16, TEAL)\n            put_text(img, f\"Renk: {PALET[aktif_renk_idx][1]}\", (22, 95), 14, WHITE)\n            put_text(img, f\"Fırça: {firca_kalinlik} px  ·  Geri al: [z]\", (22, 117), 12, GRAY)\n            for i, line in enumerate(log):\n                put_text(img, line, (22, 140 + 16 * i), 11, AMBER if \"silindi\" in line else WHITE)\n\n            # Yumrukla silme ilerleme çubuğu\n            if silme_orani > 0.05:\n                cx = canvas.width // 2\n                cy = canvas.height - 96\n                panel(img, cx - 130, cy - 22, cx + 130, cy + 20, alpha=0.85)\n                put_text(img, f\"Yumruk tut -> Siliniyor %{int(silme_orani * 100)}\", (cx - 116, cy - 16), 14, AMBER)\n                cv2.rectangle(img, (cx - 116, cy + 6), (cx + 116, cy + 14), GRAY, 1)\n                cv2.rectangle(img, (cx - 116, cy + 6), (cx - 116 + int(232 * silme_orani), cy + 14), AMBER, -1)\n\n            if son_bildirim and time.monotonic() < bildirim_bitis:\n                put_text(img, son_bildirim, (canvas.width // 2 - 160, 74), 15, TEAL, bg=INK)\n\n            if hand:\n                draw_pinch_gauge(img, state.pinch_value, state.pinching, canvas.width - 245, 52)\n\n            alt_mesaj = (\n                \"İşaret: Yaz · Üst kutuya dokun veya 2-5 parmak: Renk · Yumruk: Sil · [z] Geri Al · [F] Özellikler\"\n                if hand else result.status + \"  ·  [F] Özellikler\"\n            )\n            status_line(img, alt_mesaj, \"ok\" if hand else \"warn\")\n\n            key = loop.show(img)\n            if ord(\"1\") <= key <= ord(\"5\"):\n                aktif_renk_idx = key - ord(\"1\")\n                son_bildirim = f\"Renk -> {PALET[aktif_renk_idx][1]}\"\n                bildirim_bitis = time.monotonic() + 1.5\n            elif key in (ord(\"n\"), ord(\"N\")):\n                neon_on = not neon_on\n                son_bildirim = f\"Neon parıltı: {'AÇIK' if neon_on else 'KAPALI'}\"\n                bildirim_bitis = time.monotonic() + 1.5\n            elif key in (ord(\"z\"), ord(\"Z\")) and undo_stack:\n                drawing.layer[:] = undo_stack.pop()\n                son_bildirim = \"Son çizim geri alındı!\"\n                bildirim_bitis = time.monotonic() + 1.5\n            elif key == ord(\"c\"):\n                undo_stack.append(drawing.layer.copy())\n                drawing.clear()\n                son_bildirim = \"Tuval temizlendi! (z: geri al)\"\n                bildirim_bitis = time.monotonic() + 1.5\n            elif key == ord(\"s\"):\n                dosya = f\"cizim_{int(time.time())}.png\"\n                cv2.imwrite(dosya, img)\n                son_bildirim = f\"Kaydedildi: {dosya}\"\n                bildirim_bitis = time.monotonic() + 2.2\n                print(f\"Çizim kaydedildi: {dosya}\")\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "09_cilt_bolgeleri.py": "\"\"\"09 - Cilt analiz bölgelerinin çıkarılması\n\nÖğrenme hedefi: Yüz noktalarından alın ve yanak maskeleri oluşturmak; göz, kaş\nve dudakları dışarıda bırakmak; saçı segmentasyon modeliyle ayırmak.\n\nÇalıştırma : python examples/09_cilt_bolgeleri.py\nKullanım   : s: segmentasyon modelini aç/kapat (karşılaştırma için)   q: çıkış\n\"\"\"\n\nimport _yol  # noqa: F401\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import GRAY, WHITE, panel, put_text, status_line\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom face.tracker import FaceTracker\nfrom skin.overlay import REGION_COLORS, disclaimer, draw_regions\nfrom skin.regions import build_region_masks\n\n\ndef main():\n    args = build_parser(\"Cilt analiz bölgeleri\").parse_args()\n    prepare = FramePreparer(config.PROCESS_WIDTH)\n    segmenter, use_seg = None, False\n    try:\n        from skin.segmenter import SkinSegmenter\n        segmenter, use_seg = SkinSegmenter(), True\n    except ModelMissingError as exc:\n        print(f\"Segmentasyon olmadan devam ediliyor: {exc}\")\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            FaceTracker() as faces, DisplayLoop(\n                \"VISION LAB - 09 Cilt bolgeleri\",\n                args,\n                help_title=\"09 · Cilt Analiz Bölgeleri & Saç/Göz Dışlama\",\n                help_lines=[\n                    \"Amaç: Yüz noktalarından alın ve yanak maskeleri çıkarmak; göz, dudak ve saçı dışarıda bırakmak.\",\n                    \"• [s] Segmentasyon (saç/arka plan ayırma) modelini aç/kapat ve kalan alan yüzdesini kıyasla.\",\n                    \"• Koyu alanlar analize dahil edilmeyen (dışlanan) bölgelerdir.\",\n                    \"• [F] Bu rehberi aç/kapat  ·  [Q / Esc] Çıkış.\",\n                ],\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            result = faces.process(frame)\n            canvas = Canvas(frame, mirror=not args.no_mirror)\n            regions = None\n            if len(result.faces) == 1:\n                face = result.faces[0]\n                seg = segmenter.segment(canvas.image) if (use_seg and segmenter) else None\n                regions = build_region_masks(canvas.image, canvas.pts(face.points), face.width_px * canvas.scale,\n                                             config.SKIN_ROI_EROSION_RATIO, seg)\n                draw_regions(canvas.image, regions)\n            canvas.flip()\n            img = canvas.image\n            disclaimer(img)\n            if regions:\n                panel(img, 12, 40, 300, 186)\n                put_text(img, f\"yöntem: {regions.method}\", (24, 48), 15, WHITE)\n                for i, (name, frac) in enumerate(regions.coverage.items()):\n                    put_text(img, f\"{name}: kalan alan %{frac * 100:.0f}\", (24, 76 + 26 * i), 15, REGION_COLORS[name])\n                put_text(img, \"koyu alanlar: dışarıda bırakılan\", (24, 160), 13, GRAY)\n                status_line(img, \"1 yüz: bölgeler çıkarıldı\", \"ok\")\n            else:\n                status_line(img, \"Tek bir yüz bekleniyor.\" if result.faces else result.status, \"warn\")\n            if loop.show(img) == ord(\"s\") and segmenter:\n                use_seg = not use_seg\n    if segmenter:\n        segmenter.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "10_cilt_analizi.py": "\"\"\"10 - Açıklanabilir cilt görünümü analizi (tek kare)\n\nÖğrenme hedefi: Kalite kontrolünden geçen tek bir kareden açıklanabilir\ngöstergeler ve ısı haritaları üretmek; kalite yetersizse sonuç üretmemek.\n\nÇalıştırma : python examples/10_cilt_analizi.py\nOtomatik   : python examples/10_cilt_analizi.py --otomatik\nKullanım   : boşluk: analiz için kare al | 1-4: harita seç | f: özellikler | q: çıkış\n\nEğitim amaçlı görüntü analizi; tıbbi tanı değildir. Görüntüler kaydedilmez.\n\"\"\"\n\nimport _yol  # noqa: F401\n\nimport time\n\nimport numpy as np\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import status_line\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom face.tracker import FaceTracker\nfrom skin.analyzer import SkinAnalyzer\nfrom skin.overlay import MAP_KEYS, disclaimer, draw_quality, result_panel\n\nPREVIEW_INTERVAL_S = 0.5     # kalite önizlemesinin güncellenme aralığı\n\nHELP_LINES = [\n    \"Amaç: Işık, poz ve netlik kalite kontrolünden geçen tek kareden açıklanabilir cilt ısı haritası üretmek.\",\n    \"• [Boşluk / Space] Soldaki 6 kalite göstergesi yeşil olunca tek kare analiz alır.\",\n    \"• [1] Kızarıklık (Δa*)  ·  [2] Parlama  ·  [3] Doku  ·  [4] Renk farkı (ΔE) haritaları.\",\n    \"• İki yanak arasındaki ΔE farkı genellikle ışığın tek taraftan gelmesinden kaynaklanır.\",\n    \"• Etik Not: Yalnızca eğitim amaçlı görüntü analizidir; tıbbi tanı değildir.\",\n]\n\n\ndef main():\n    parser = build_parser(\"Cilt görünümü analizi\")\n    parser.add_argument(\"--otomatik\", action=\"store_true\",\n                        help=\"Kalite uygun olduğunda birkaç saniyede bir otomatik analiz yap.\")\n    parser.add_argument(\"--segmentasyonsuz\", action=\"store_true\", help=\"Segmentasyon modelini kullanma.\")\n    args = parser.parse_args()\n    prepare = FramePreparer(config.PROCESS_WIDTH)\n    analyzer = SkinAnalyzer(use_segmenter=not args.segmentasyonsuz)\n    print(analyzer.segmenter_note)\n    preview, captured, map_name = None, None, MAP_KEYS[0]\n    last_preview = last_auto = 0.0\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            FaceTracker() as faces, \\\n            DisplayLoop(\n                \"VISION LAB - 10 Cilt analizi\",\n                args,\n                help_title=\"10 · Açıklanabilir Cilt Görünümü Analizi\",\n                help_lines=HELP_LINES,\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            result = faces.process(frame)\n            now = time.monotonic()\n\n            # Kalite önizlemesi düşük sıklıkta çalışır; yüz takibi her karede devam eder.\n            if now - last_preview >= PREVIEW_INTERVAL_S:\n                preview = analyzer.analyze(frame.full_bgr, result.faces, frame.scale_to_full)\n                last_preview = now\n                if args.otomatik and preview.metrics is not None and \\\n                        now - last_auto >= config.AUTO_ANALYSIS_INTERVAL_S:\n                    captured, last_auto = preview, now\n\n            # 820px genişlik: 16:9 kamerada ~461px yükseklik -> sağ panel hiç taşmaz\n            canvas = Canvas(frame, width=820, mirror=not args.no_mirror)\n            canvas.flip()\n            img = canvas.image\n            disclaimer(img)\n            if preview is not None:\n                draw_quality(img, preview.quality, 12, 38)\n            hint = \"Boşluk: analiz al  ·  1-4: harita  ·  [F] Özellikler\" if preview is not None and preview.quality.ok else \\\n                (\"Uygun görüntü bekleniyor: \" + (preview.quality.first_problem if preview else \"\"))\n            status_line(img, hint, \"ok\" if preview is not None and preview.quality.ok else \"warn\")\n\n            side = result_panel(captured, map_name, height=img.shape[0], width=430)\n            key = loop.show(np.hstack([img, side]))\n            if key == ord(\" \"):\n                captured = analyzer.analyze(frame.full_bgr, result.faces, frame.scale_to_full)\n                print(captured.message, f\"({captured.elapsed_ms:.0f} ms)\")\n            elif ord(\"1\") <= key <= ord(\"4\"):\n                map_name = MAP_KEYS[key - ord(\"1\")]\n    analyzer.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "bonus1_sanal_kalem.py": "\"\"\"BONUS PROJE 1 — Sanal Çizim Tahtası (HSV Renk Takibi)\n\nYalnızca OpenCV ve NumPy kullanır (ek model gerekmez).\nElinizdeki parlak mavi (veya 1/2/3 tuşuyla seçtiğiniz) bir kalem kapağını\nkamerada takip ederek havada çizim yapmanızı sağlar.\n\nÇalıştırma : python bonus_projeler/bonus1_sanal_kalem.py\nTuşlar     : 1: Mavi takip | 2: Yeşil takip | 3: Sarı takip\n             c: Tuvali temizle | f: Özellikler | q: Çıkış\n\"\"\"\n\nimport time\nimport cv2\nimport numpy as np\n\n# HSV renk aralıkları: (alt_sınır, üst_sınır, çizim_BGR_rengi, etiket)\nRENKLER = {\n    \"1\": ((95, 110, 70), (130, 255, 255), (255, 190, 60), \"MAVI\"),\n    \"2\": ((38, 80, 60), (85, 255, 255), (170, 232, 108), \"YESIL\"),\n    \"3\": ((18, 110, 90), (35, 255, 255), (90, 220, 255), \"SARI\"),\n}\n\n\ndef kamera_ac():\n    for idx in (0, 1):\n        c = cv2.VideoCapture(idx)\n        if not c.isOpened():\n            c.release()\n            continue\n        for _ in range(20):\n            ok, frm = c.read()\n            if ok and frm is not None and frm.size > 0:\n                return c\n            time.sleep(0.04)\n        c.release()\n    return None\n\n\ndef main():\n    cap = kamera_ac()\n    if cap is None:\n        print(\"Kamera açılamadı veya görüntü gelmedi. Kamera iznini kontrol edin.\")\n        return\n\n    WIN = \"BONUS 1 - Sanal Cizim Tahtasi (f: ozellikler | q: cikis)\"\n    flags = cv2.WINDOW_NORMAL | (cv2.WINDOW_KEEPRATIO if hasattr(cv2, \"WINDOW_KEEPRATIO\") else 0)\n    cv2.namedWindow(WIN, flags)\n\n    aktif = \"1\"\n    tuval = None\n    onceki = None\n    show_help = False\n    sized = False\n\n    try:\n        while True:\n            ok, frame = cap.read()\n            if not ok:\n                break\n            frame = cv2.flip(frame, 1)\n            h, w = frame.shape[:2]\n            if not sized:\n                scale = min(1.0, 1120 / max(w, 1), 680 / max(h, 1))\n                cv2.resizeWindow(WIN, int(w * scale), int(h * scale))\n                sized = True\n            if tuval is None:\n                tuval = np.zeros_like(frame)\n\n            alt, ust, renk, ad = RENKLER[aktif]\n            hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)\n            maske = cv2.inRange(hsv, np.array(alt), np.array(ust))\n\n            # Gürültüyü temizle\n            kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (7, 7))\n            maske = cv2.morphologyEx(maske, cv2.MORPH_OPEN, kernel)\n            maske = cv2.morphologyEx(maske, cv2.MORPH_DILATE, kernel)\n\n            konturlar, _ = cv2.findContours(maske, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)\n            if konturlar:\n                en_buyuk = max(konturlar, key=cv2.contourArea)\n                if cv2.contourArea(en_buyuk) > 450:\n                    (x, y), r = cv2.minEnclosingCircle(en_buyuk)\n                    merkez = (int(x), int(y))\n                    cv2.circle(frame, merkez, int(r), renk, 2)\n                    cv2.circle(frame, merkez, 6, (255, 255, 255), -1)\n                    if onceki is not None:\n                        cv2.line(tuval, onceki, merkez, renk, 6, cv2.LINE_AA)\n                    onceki = merkez\n                else:\n                    onceki = None\n            else:\n                onceki = None\n\n            # Çizimi kamera görüntüsüyle birleştir\n            gri_tuval = cv2.cvtColor(tuval, cv2.COLOR_BGR2GRAY)\n            _, ters_maske = cv2.threshold(gri_tuval, 10, 255, cv2.THRESH_BINARY_INV)\n            arka = cv2.bitwise_and(frame, frame, mask=ters_maske)\n            sonuc = cv2.add(arka, tuval)\n\n            cv2.rectangle(sonuc, (0, 0), (w, 40), (24, 18, 28), -1)\n            cv2.putText(\n                sonuc,\n                f\"Takip: {ad}  (1:Mavi 2:Yesil 3:Sari | c:Temizle | [F] Ozellikler | q:Cikis)\",\n                (14, 27),\n                cv2.FONT_HERSHEY_SIMPLEX,\n                0.56,\n                (170, 232, 108),\n                2,\n                cv2.LINE_AA,\n            )\n\n            if show_help:\n                ov = sonuc.copy()\n                cv2.rectangle(ov, (w // 2 - 270, h // 2 - 90), (w // 2 + 270, h // 2 + 90), (24, 18, 28), -1)\n                cv2.addWeighted(ov, 0.88, sonuc, 0.12, 0, sonuc)\n                cv2.rectangle(sonuc, (w // 2 - 270, h // 2 - 90), (w // 2 + 270, h // 2 + 90), (170, 232, 108), 2)\n                satirlar = [\n                    \"BONUS 1 - Sanal Cizim Tahtasi (HSV)\",\n                    \"Amac: Renkli bir kalem kapagini HSV maskesiyle takip edip cizmek.\",\n                    \"- [1] Mavi  |  [2] Yesil  |  [3] Sari nesne takibi sec\",\n                    \"- [c] Tuvali temizle  |  [F] Kapat  |  [q / Esc] Cikis\",\n                ]\n                for i, s in enumerate(satirlar):\n                    cv2.putText(sonuc, s, (w // 2 - 252, h // 2 - 48 + i * 34),\n                                cv2.FONT_HERSHEY_SIMPLEX, 0.50, (233, 239, 242) if i else (170, 232, 108), 1, cv2.LINE_AA)\n\n            cv2.imshow(WIN, sonuc)\n\n            tus = cv2.waitKey(1) & 0xFF\n            if tus in (ord(\"q\"), 27):\n                break\n            elif tus in (ord(\"f\"), ord(\"F\")):\n                show_help = not show_help\n            elif tus == ord(\"c\"):\n                tuval[:] = 0\n            elif tus in (ord(\"1\"), ord(\"2\"), ord(\"3\")):\n                aktif = chr(tus)\n                onceki = None\n    finally:\n        cap.release()\n        cv2.destroyAllWindows()\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "bonus2_belge_tarayici.py": "\"\"\"BONUS PROJE 2 — Akıllı Belge Tarayıcı (CamScanner Mantığı)\n\nYalnızca OpenCV ve NumPy kullanır.\nKameraya tutulan dikdörtgen bir kağıdın veya kimlik/not kartının 4 köşesini\nCanny kenar tespiti + kontur yaklaşımı ile bulur ve 's' tuşuna basıldığında\nperspektif dönüşümü (warpPerspective) ile düz taranmış belgeye çevirir.\n\nÇalıştırma : python bonus_projeler/bonus2_belge_tarayici.py\nTuşlar     : s: Belgeyi tara | f: Özellikler | q: Çıkış\n\"\"\"\n\nimport time\nimport cv2\nimport numpy as np\n\n\ndef koseleri_sirala(pts: np.ndarray) -> np.ndarray:\n    \"\"\"4 köşeyi sol-üst, sağ-üst, sağ-alt, sol-alt sırasına dizer.\"\"\"\n    pts = pts.reshape(4, 2).astype(\"float32\")\n    sira = np.zeros((4, 2), dtype=\"float32\")\n    toplam = pts.sum(axis=1)\n    fark = np.diff(pts, axis=1)\n    sira[0] = pts[np.argmin(toplam)]  # sol-üst\n    sira[2] = pts[np.argmax(toplam)]  # sağ-alt\n    sira[1] = pts[np.argmin(fark)]    # sağ-üst\n    sira[3] = pts[np.argmax(fark)]    # sol-alt\n    return sira\n\n\ndef perspektif_duzelt(img: np.ndarray, kose: np.ndarray) -> np.ndarray:\n    rect = koseleri_sirala(kose)\n    tl, tr, br, bl = rect\n    w = int(max(np.linalg.norm(br - bl), np.linalg.norm(tr - tl)))\n    h = int(max(np.linalg.norm(tr - br), np.linalg.norm(tl - bl)))\n    w, h = max(w, 200), max(h, 200)\n    hedef = np.array([[0, 0], [w - 1, 0], [w - 1, h - 1], [0, h - 1]], dtype=\"float32\")\n    M = cv2.getPerspectiveTransform(rect, hedef)\n    return cv2.warpPerspective(img, M, (w, h))\n\n\ndef kamera_ac():\n    for idx in (0, 1):\n        c = cv2.VideoCapture(idx)\n        if not c.isOpened():\n            c.release()\n            continue\n        for _ in range(20):\n            ok, frm = c.read()\n            if ok and frm is not None and frm.size > 0:\n                return c\n            time.sleep(0.04)\n        c.release()\n    return None\n\n\ndef main():\n    cap = kamera_ac()\n    if cap is None:\n        print(\"Kamera açılamadı veya görüntü gelmedi.\")\n        return\n\n    WIN = \"BONUS 2 - Akilli Belge Tarayici (f: ozellikler | q: cikis)\"\n    flags = cv2.WINDOW_NORMAL | (cv2.WINDOW_KEEPRATIO if hasattr(cv2, \"WINDOW_KEEPRATIO\") else 0)\n    cv2.namedWindow(WIN, flags)\n\n    show_help = False\n    sized = False\n\n    try:\n        while True:\n            ok, frame = cap.read()\n            if not ok:\n                break\n            h, w = frame.shape[:2]\n            if not sized:\n                scale = min(1.0, 1120 / max(w, 1), 680 / max(h, 1))\n                cv2.resizeWindow(WIN, int(w * scale), int(h * scale))\n                sized = True\n\n            gri = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)\n            blur = cv2.GaussianBlur(gri, (5, 5), 0)\n            kenar = cv2.Canny(blur, 55, 150)\n            kenar = cv2.dilate(kenar, np.ones((3, 3), np.uint8), iterations=1)\n\n            konturlar, _ = cv2.findContours(kenar, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)\n            konturlar = sorted(konturlar, key=cv2.contourArea, reverse=True)[:5]\n\n            belge = None\n            for c in konturlar:\n                if cv2.contourArea(c) < 12000:\n                    continue\n                cevre = cv2.arcLength(c, True)\n                yaklasik = cv2.approxPolyDP(c, 0.02 * cevre, True)\n                if len(yaklasik) == 4:\n                    belge = yaklasik\n                    break\n\n            goster = frame.copy()\n            if belge is not None:\n                cv2.drawContours(goster, [belge], -1, (170, 232, 108), 3)\n                durum = \"Belge bulundu! Taramak icin [s] tusuna bas  |  [F] Ozellikler\"\n            else:\n                durum = \"Koyu zemin uzerinde beyaz kagit gosterin  |  [F] Ozellikler\"\n\n            cv2.rectangle(goster, (0, 0), (w, 40), (24, 18, 28), -1)\n            cv2.putText(goster, durum, (14, 27), cv2.FONT_HERSHEY_SIMPLEX, 0.58, (170, 232, 108), 2, cv2.LINE_AA)\n\n            if show_help:\n                ov = goster.copy()\n                cv2.rectangle(ov, (w // 2 - 270, h // 2 - 90), (w // 2 + 270, h // 2 + 90), (24, 18, 28), -1)\n                cv2.addWeighted(ov, 0.88, goster, 0.12, 0, goster)\n                cv2.rectangle(goster, (w // 2 - 270, h // 2 - 90), (w // 2 + 270, h // 2 + 90), (170, 232, 108), 2)\n                satirlar = [\n                    \"BONUS 2 - Akilli Belge Tarayici (CamScanner)\",\n                    \"Amac: Kagidin 4 kosesini bulup perspektif duzeltmesi yapmak.\",\n                    \"- Koyu masa uzerinde beyaz bir kagidi kameraya tutun.\",\n                    \"- Yesil cerceve cikinca [s] ile tarayin  |  [F] Kapat  |  [q] Cikis\",\n                ]\n                for i, s in enumerate(satirlar):\n                    cv2.putText(goster, s, (w // 2 - 252, h // 2 - 48 + i * 34),\n                                cv2.FONT_HERSHEY_SIMPLEX, 0.50, (233, 239, 242) if i else (170, 232, 108), 1, cv2.LINE_AA)\n\n            cv2.imshow(WIN, goster)\n\n            tus = cv2.waitKey(1) & 0xFF\n            if tus in (ord(\"q\"), 27):\n                break\n            elif tus in (ord(\"f\"), ord(\"F\")):\n                show_help = not show_help\n            elif tus == ord(\"s\") and belge is not None:\n                duz = perspektif_duzelt(frame, belge)\n                duz_gri = cv2.cvtColor(duz, cv2.COLOR_BGR2GRAY)\n                taranmis = cv2.adaptiveThreshold(\n                    duz_gri, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY, 15, 8\n                )\n                cv2.namedWindow(\"Taranmis Belge (PDF Gorunumu)\", flags)\n                cv2.imshow(\"Taranmis Belge (PDF Gorunumu)\", taranmis)\n    finally:\n        cap.release()\n        cv2.destroyAllWindows()\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "bonus3_el_kalp_efekti.py": "\"\"\"BONUS PROJE 3 — SEIS NEON AR VFX STÜDYOSU (Gerçek Bloom Parıltılı Bilgisayarlı Görü Efekt Motoru)\n\nMevcut vision-workshop ortamındaki OpenCV + NumPy + MediaPipe HandTracker (max_hands=2)\nile çalışır; ek paket veya model indirmenize gerek yoktur.\n\nGerçek Zamanlı VFX Motoru (Ayrı Glow Katmanı + Gaussian Bloom + Additive Blending):\n  1. 🫶 İKİ ELLE KALP     : Gerçek neon bloom parıltılı kalp + şarj barı + %100'de ŞOK DALGASI & 60 parçacık patlaması!\n  2. ⚡ İKİ AÇIK EL       : İki avuç arasında canlı plazma şimşek arkı + mesafeye göre büyüyen enerji küresi!\n  3. 🖐️ TEK AÇIK EL       : Avuç içinde dönen Doctor Strange / siber bilgisayarlı görü mandala halkası!\n  4. ☝️ İŞARET PARMAĞI    : Havada sönerek kaybolan neon ışık kurdelesi (lazer izi) ve kıvılcımlar!\n  5. ✌️ V İŞARETİ         : \"SEIS IT WORKSHOP!\" neon rozeti + konfeti yağmuru!\n  6. 👍 BAŞPARMAK YUKARI  : Altın yıldız yağmuru + \"HARİKA! +100\" efekti!\n  7. ✊ YUMRUK            : Etraftaki enerji parçacıklarını avuca çeken çekim alanı!\n\nTuşlar:\n  m : Arka plan modu (Sinema Neon / Doğal Kamera / TRON Kenar Modu)\n  s : Hatıra fotoğrafı kaydet (PNG)\n  c : Tüm efektleri ve izi temizle\n  q : Çıkış\n\"\"\"\n\nimport math\nimport random\nimport sys\nimport time\nfrom collections import deque\nfrom pathlib import Path\n\nimport cv2\nimport numpy as np\n\n# src klasörünü otomatik bul (hem atolye-baslangic/bonus_projeler hem Gemini/bonus_projeler için)\nfor _p in Path(__file__).resolve().parents:\n    if (_p / \"src\").is_dir():\n        if str(_p / \"src\") not in sys.path:\n            sys.path.insert(0, str(_p / \"src\"))\n        break\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import panel, put_text, status_line\nfrom common.fps import FPSMeter\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom hands.gestures import classify_static, finger_states\nfrom hands.tracker import HandTracker\n\n# Renk Paleti (BGR)\nMINT = (170, 232, 108)\nCYAN = (255, 225, 80)\nCREAM = (218, 236, 247)\nPEACH = (130, 161, 235)\nPINK = (165, 70, 255)\nMAGENTA = (220, 60, 255)\nGOLD = (80, 215, 255)\nPLUM_BG = (22, 8, 36)\n\nMODLAR = [\"Sinema Neon\", \"Dogal Kamera\", \"TRON Kenar\"]\n\n\ndef kalp_pts(cx: float, cy: float, boyut: float, n: int = 64) -> np.ndarray:\n    t = np.linspace(0, 2 * math.pi, n)\n    x = 16 * np.sin(t) ** 3\n    y = -(13 * np.cos(t) - 5 * np.cos(2 * t) - 2 * np.cos(3 * t) - np.cos(4 * t))\n    return np.column_stack((cx + x * (boyut / 16.0), cy + y * (boyut / 16.0))).astype(np.int32)\n\n\ndef yildiz_pts(cx: float, cy: float, dis_r: float, aci: float = 0.0) -> np.ndarray:\n    ic_r = dis_r * 0.42\n    pts = []\n    for i in range(10):\n        r = dis_r if i % 2 == 0 else ic_r\n        a = aci + i * math.pi / 5.0 - math.pi / 2.0\n        pts.append((cx + r * math.cos(a), cy + r * math.sin(a)))\n    return np.array(pts, dtype=np.int32)\n\n\ndef neon_el_iskeleti(glow: np.ndarray, pts: np.ndarray, renk=MINT):\n    \"\"\"El iskeletini parlak neon çizgiler ve eklem düğümleri olarak glow katmanına çizer.\"\"\"\n    baglar = [\n        (0, 1), (1, 2), (2, 3), (3, 4),\n        (0, 5), (5, 6), (6, 7), (7, 8),\n        (5, 9), (9, 10), (10, 11), (11, 12),\n        (9, 13), (13, 14), (14, 15), (15, 16),\n        (13, 17), (0, 17), (17, 18), (18, 19), (19, 20),\n    ]\n    for a, b in baglar:\n        p1 = (int(pts[a][0]), int(pts[a][1]))\n        p2 = (int(pts[b][0]), int(pts[b][1]))\n        cv2.line(glow, p1, p2, renk, 2, cv2.LINE_AA)\n    for i, p in enumerate(pts):\n        r = 5 if i in (4, 8, 12, 16, 20) else 3\n        c = CREAM if i in (4, 8) else renk\n        cv2.circle(glow, (int(p[0]), int(p[1])), r, c, -1, cv2.LINE_AA)\n\n\ndef siber_mandala_ciz(glow: np.ndarray, cx: int, cy: int, r: int, faz: float, renk=MINT):\n    \"\"\"Dönen çok katmanlı Doctor Strange / Bilgisayarlı Görü enerji halkası.\"\"\"\n    cv2.circle(glow, (cx, cy), r, renk, 2, cv2.LINE_AA)\n    cv2.circle(glow, (cx, cy), int(r * 0.72), CYAN, 1, cv2.LINE_AA)\n    cv2.circle(glow, (cx, cy), int(r * 0.35), CREAM, 1, cv2.LINE_AA)\n\n    # Dönen yaylar\n    aci = int((faz * 6) % 360)\n    for off in (0, 90, 180, 270):\n        cv2.ellipse(glow, (cx, cy), (r + 10, r + 10), 0, aci + off, aci + off + 48, renk, 3, cv2.LINE_AA)\n        cv2.ellipse(glow, (cx, cy), (int(r * 0.85), int(r * 0.85)), 0, -aci + off, -aci + off + 38, PEACH, 2, cv2.LINE_AA)\n\n    # Dönen iç altıgen\n    hex_pts = []\n    for k in range(6):\n        a = faz * 0.06 + k * (math.pi / 3.0)\n        hex_pts.append((int(cx + math.cos(a) * r * 0.68), int(cy + math.sin(a) * r * 0.68)))\n    cv2.polylines(glow, [np.array(hex_pts, dtype=np.int32)], True, renk, 1, cv2.LINE_AA)\n\n\ndef plazma_simsek_ciz(glow: np.ndarray, p1: tuple[int, int], p2: tuple[int, int], faz: float):\n    \"\"\"İki avuç arasında canlı kırılan plazma şimşek arkı ve orta enerji küresi çizer.\"\"\"\n    x1, y1 = p1\n    x2, y2 = p2\n    mesafe = max(1.0, math.hypot(x2 - x1, y2 - y1))\n    nx, ny = -(y2 - y1) / mesafe, (x2 - x1) / mesafe  # dik vektör\n\n    # 2 katmanlı kırık şimşek kolu\n    for katman, (renk, kalinlik, genlik) in enumerate([(CYAN, 4, 22), (CREAM, 2, 12)]):\n        adim = 14\n        noktalar = []\n        for i in range(adim + 1):\n            t = i / adim\n            bx = x1 + (x2 - x1) * t\n            by = y1 + (y2 - y1) * t\n            sapma = 0.0 if i in (0, adim) else random.uniform(-genlik, genlik) * math.sin(t * math.pi)\n            noktalar.append((int(bx + nx * sapma), int(by + ny * sapma)))\n        cv2.polylines(glow, [np.array(noktalar, dtype=np.int32)], False, renk, kalinlik, cv2.LINE_AA)\n\n    # Ortada mesafeye göre büyüyen enerji küresi\n    mx, my = (x1 + x2) // 2, (y1 + y2) // 2\n    kure_r = int(min(54, max(16, mesafe * 0.14)) + 4 * math.sin(faz * 0.4))\n    cv2.circle(glow, (mx, my), kure_r, CYAN, 3, cv2.LINE_AA)\n    cv2.circle(glow, (mx, my), max(6, kure_r // 2), CREAM, -1, cv2.LINE_AA)\n\n\ndef kalp_algila(hands) -> tuple[bool, tuple[float, float] | None]:\n    if len(hands) < 2:\n        return False, None\n    h1, h2 = hands[0].points, hands[1].points\n    avuc = max(float(np.linalg.norm(h1[0] - h1[9])), float(np.linalg.norm(h2[0] - h2[9])), 1.0)\n    bas_d = float(np.linalg.norm(h1[4] - h2[4])) / avuc\n    isr_d = float(np.linalg.norm(h1[8] - h2[8])) / avuc\n    ust_y = (h1[8][1] + h2[8][1]) / 2.0\n    alt_y = (h1[4][1] + h2[4][1]) / 2.0\n    if bas_d < 0.78 and isr_d < 0.88 and ust_y < alt_y + 0.25 * avuc:\n        return True, ((h1[4][0] + h2[4][0] + h1[8][0] + h2[8][0]) / 4.0, (ust_y + alt_y) / 2.0)\n    return False, None\n\n\nclass Parcacik:\n    def __init__(self, x, y, vx, vy, boyut, tur, renk, omur=36):\n        self.x, self.y = float(x), float(y)\n        self.vx, self.vy = float(vx), float(vy)\n        self.boyut = float(boyut)\n        self.tur = tur  # \"kalp\" | \"yildiz\" | \"konfeti\" | \"kivilcim\"\n        self.renk = renk\n        self.omur = omur\n        self.max_omur = omur\n        self.faz = random.uniform(0, 6.28)\n\n    def guncelle_ve_ciz(self, glow: np.ndarray) -> bool:\n        self.x += self.vx + (math.sin(self.faz) * 0.8 if self.tur == \"kalp\" else 0.0)\n        self.y += self.vy\n        self.vx *= 0.97\n        self.vy += 0.07 if self.tur == \"konfeti\" else -0.02\n        self.faz += 0.22\n        self.omur -= 1\n        if self.omur <= 0:\n            return False\n\n        oran = self.omur / self.max_omur\n        b = max(3.0, self.boyut * (0.45 + 0.55 * oran))\n        renk = tuple(int(c * (0.35 + 0.65 * oran)) for c in self.renk)\n        ix, iy = int(self.x), int(self.y)\n        if self.tur == \"kalp\":\n            cv2.fillPoly(glow, [kalp_pts(ix, iy, b, n=28)], renk, cv2.LINE_AA)\n        elif self.tur == \"yildiz\":\n            cv2.fillPoly(glow, [yildiz_pts(ix, iy, b, self.faz)], renk, cv2.LINE_AA)\n        else:\n            cv2.circle(glow, (ix, iy), max(2, int(b * 0.42)), renk, -1, cv2.LINE_AA)\n        return True\n\n\ndef bloom_birlestir(arka: np.ndarray, glow: np.ndarray) -> np.ndarray:\n    \"\"\"Glow katmanına gerçek Gaussian bloom uygulayıp sahneye ekler (additive neon).\"\"\"\n    # Hızlı bloom için yarı çözünürlükte bulanıklaştırıp geri büyüt (yüksek FPS!)\n    h, w = glow.shape[:2]\n    kucuk = cv2.resize(glow, (w // 2, h // 2), interpolation=cv2.INTER_LINEAR)\n    bul = cv2.GaussianBlur(kucuk, (21, 21), 0)\n    bloom = cv2.resize(bul, (w, h), interpolation=cv2.INTER_LINEAR)\n    sonuc = cv2.add(arka, bloom)\n    return cv2.add(sonuc, glow)\n\n\ndef main():\n    args = build_parser(\"SEIS Neon AR VFX Stüdyosu\").parse_args()\n    prepare, fps = FramePreparer(config.PROCESS_WIDTH), FPSMeter()\n\n    parcaciklar: list[Parcacik] = []\n    sok_dalgalari: list[list[float]] = []  # [cx, cy, r, max_r]\n    lazer_izi: deque = deque(maxlen=28)\n\n    faz = 0.0\n    kalp_sarj = 0.0\n    smooth_heart = None\n    mod_idx = 0\n    bildirim = \"\"\n    bildirim_bitis = 0.0\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            HandTracker(max_hands=2) as hands, \\\n            DisplayLoop(\n                \"SEIS NEON AR VFX STUDYOSU\",\n                args,\n                help_title=\"Bonus 3 · SEIS Neon AR El Jestleri VFX Stüdyosu\",\n                help_lines=[\n                    \"Amaç: 21 el noktasından 7 farklı canlı neon AR efekti ve parçacık fiziği üretmek.\",\n                    \"• 🫶 İki Elle Kalp: Neon kalp + %100 dolunca şok dalgası patlaması!\",\n                    \"• ⚡ İki Açık El: Avuçlar arası canlı plazma şimşek arkı.\",\n                    \"• ☝️ İşaret / 🖐️ Açık El / ✌️ V / 👍 Başparmak / ✊ Yumruk: Lazer, mandala, konfeti, yıldız!\",\n                    \"• [m] Sahne modu (Sinema / Doğal / TRON)  ·  [s] Hatıra PNG kaydet  ·  [F] Kapat\",\n                ],\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            faz += 1.0\n            frame = prepare(raw)\n            result = hands.process(frame)\n\n            canvas = Canvas(frame, mirror=not args.no_mirror)\n            canvas.flip()\n            arka = canvas.image\n            h, w = arka.shape[:2]\n\n            # Arka plan atmosfer modu\n            if mod_idx == 0:  # Sinema Neon (neonların patlaması için hafif koyu bordo tonu)\n                arka = (arka.astype(np.float32) * 0.68).astype(np.uint8)\n            elif mod_idx == 2:  # TRON Kenar Modu\n                gri = cv2.cvtColor(arka, cv2.COLOR_BGR2GRAY)\n                kenar = cv2.Canny(cv2.GaussianBlur(gri, (5, 5), 0), 55, 145)\n                arka = np.zeros_like(arka)\n                arka[kenar > 0] = (95, 130, 62)\n\n            # Siyah neon glow katmanı (tüm parlayan efektler buraya çizilir)\n            glow = np.zeros_like(arka)\n\n            # Ekran koordinatlarına çevrilmiş eller\n            ekran_elleri = []\n            for hand in result.hands:\n                e_pts = np.array([canvas.screen(pt) for pt in hand.points], dtype=np.float32)\n                jest = classify_static(finger_states(hand.points))\n                ekran_elleri.append((e_pts, jest))\n                neon_el_iskeleti(glow, e_pts, renk=MINT if jest != \"yumruk\" else PEACH)\n\n            aktif_efekt = \"Hazır — Jestini Göster!\"\n            kalp_var, ham_merkez = kalp_algila(result.hands)\n\n            if kalp_var and ham_merkez is not None:\n                lazer_izi.clear()\n                sx, sy = canvas.screen(ham_merkez)\n                smooth_heart = (sx, sy) if smooth_heart is None else (\n                    0.35 * sx + 0.65 * smooth_heart[0], 0.35 * sy + 0.65 * smooth_heart[1]\n                )\n                cx, cy = int(smooth_heart[0]), int(smooth_heart[1])\n                kalp_sarj = min(100.0, kalp_sarj + 3.0)\n                nabiz = 48 + 10 * math.sin(faz * 0.35) + kalp_sarj * 0.16\n\n                # Neon kalp + iç parlak katman + yörünge ışıkları\n                cv2.fillPoly(glow, [kalp_pts(cx, cy, nabiz)], PINK, cv2.LINE_AA)\n                cv2.fillPoly(glow, [kalp_pts(cx, cy - nabiz * 0.05, nabiz * 0.65)], CREAM, cv2.LINE_AA)\n                for k in range(8):\n                    a = faz * 0.1 + k * (math.pi / 4.0)\n                    cv2.circle(glow, (int(cx + math.cos(a) * nabiz * 1.4), int(cy + math.sin(a) * nabiz * 1.15)),\n                               4, MINT if k % 2 == 0 else GOLD, -1, cv2.LINE_AA)\n\n                aktif_efekt = f\"KALP ALGILANDI! (Şarj: %{int(kalp_sarj)})\"\n                if int(faz) % 2 == 0:\n                    parcaciklar.append(Parcacik(\n                        cx + random.randint(-42, 42), cy + random.randint(-12, 12),\n                        random.uniform(-1.5, 1.5), random.uniform(-5.0, -2.2),\n                        random.uniform(11, 20), \"kalp\", random.choice([PINK, MAGENTA, PEACH]), omur=34,\n                    ))\n\n                # %100 dolunca ŞOK DALGASI + 60 parçacık patlaması!\n                if kalp_sarj >= 100.0:\n                    sok_dalgalari.append([cx, cy, 24.0, max(w, h) * 0.65])\n                    for _ in range(56):\n                        a = random.uniform(0, 2 * math.pi)\n                        spd = random.uniform(4.0, 12.0)\n                        parcaciklar.append(Parcacik(\n                            cx, cy, math.cos(a) * spd, math.sin(a) * spd - 1.5,\n                            random.uniform(12, 22), random.choice([\"kalp\", \"yildiz\", \"konfeti\"]),\n                            random.choice([PINK, MINT, GOLD, CYAN, CREAM]), omur=46,\n                        ))\n                    kalp_sarj = 15.0\n                    bildirim = \"SEIS KALP PATLAMASI!\"\n                    bildirim_bitis = time.monotonic() + 2.2\n            else:\n                smooth_heart = None\n                kalp_sarj = max(0.0, kalp_sarj - 3.5)\n\n                # İKİ AÇIK EL → PLAZMA ŞİMŞEK ARKI!\n                acik_eller = [e_pts for e_pts, j in ekran_elleri if j == \"acik_el\"]\n                if len(acik_eller) == 2:\n                    lazer_izi.clear()\n                    p1 = (int(acik_eller[0][9][0]), int(acik_eller[0][9][1]))\n                    p2 = (int(acik_eller[1][9][0]), int(acik_eller[1][9][1]))\n                    siber_mandala_ciz(glow, p1[0], p1[1], 38, faz, CYAN)\n                    siber_mandala_ciz(glow, p2[0], p2[1], 38, -faz, CYAN)\n                    plazma_simsek_ciz(glow, p1, p2, faz)\n                    aktif_efekt = \"PLAZMA ENERJİ ARKI! (İki Açık El)\"\n                else:\n                    isaret_aktif = False\n                    for e_pts, jest in ekran_elleri:\n                        hx, hy = int(e_pts[9][0]), int(e_pts[9][1])\n                        if jest == \"acik_el\":\n                            siber_mandala_ciz(glow, hx, hy, 46, faz, MINT)\n                            aktif_efekt = \"SİBER MANDALA HUD (Açık El)\"\n                        elif jest == \"isaret\":\n                            isaret_aktif = True\n                            ix, iy = int(e_pts[8][0]), int(e_pts[8][1])\n                            lazer_izi.append((ix, iy))\n                            cv2.circle(glow, (ix, iy), 8, CYAN, -1, cv2.LINE_AA)\n                            if int(faz) % 2 == 0:\n                                parcaciklar.append(Parcacik(\n                                    ix, iy, random.uniform(-2, 2), random.uniform(-2, 2),\n                                    random.uniform(5, 10), \"kivilcim\", random.choice([CYAN, MINT, CREAM]), omur=20,\n                                ))\n                            aktif_efekt = \"NEON LAZER ÇİZİMİ (İşaret Parmağı)\"\n                        elif jest == \"v_isareti\":\n                            aktif_efekt = \"SEIS IT WORKSHOP! (V İşareti)\"\n                            for _ in range(2):\n                                parcaciklar.append(Parcacik(\n                                    hx + random.randint(-30, 30), hy - 55,\n                                    random.uniform(-3.0, 3.0), random.uniform(-6.0, -2.5),\n                                    random.uniform(9, 15), \"konfeti\", random.choice([MINT, CREAM, PEACH]), omur=38,\n                                ))\n                        elif jest == \"basparmak_yukari\":\n                            aktif_efekt = \"HARİKA! +100 (Başparmak Yukarı)\"\n                            tx, ty = int(e_pts[4][0]), int(e_pts[4][1])\n                            if int(faz) % 2 == 0:\n                                parcaciklar.append(Parcacik(\n                                    tx + random.randint(-18, 18), ty - 10,\n                                    random.uniform(-1.8, 1.8), random.uniform(-5.2, -2.5),\n                                    random.uniform(11, 18), \"yildiz\", GOLD, omur=34,\n                                ))\n                        elif jest == \"yumruk\":\n                            aktif_efekt = \"ENERJİ TOPLANIYOR (Yumruk)\"\n                            a = random.uniform(0, 2 * math.pi)\n                            parcaciklar.append(Parcacik(\n                                hx + math.cos(a) * 95, hy + math.sin(a) * 95,\n                                -math.cos(a) * 5.2, -math.sin(a) * 5.2,\n                                9, \"kivilcim\", PEACH, omur=18,\n                            ))\n                    if not isaret_aktif and lazer_izi:\n                        lazer_izi.popleft()\n\n            # Lazer kurdelesini çiz (kuyruktan uca kalınlaşan neon şerit)\n            if len(lazer_izi) > 1:\n                pts_l = list(lazer_izi)\n                for i in range(1, len(pts_l)):\n                    kal = max(1, int(9 * (i / len(pts_l))))\n                    cv2.line(glow, pts_l[i - 1], pts_l[i], CYAN if i < len(pts_l) - 4 else CREAM, kal, cv2.LINE_AA)\n\n            # Şok dalgalarını çiz\n            yeni_dalga = []\n            for d in sok_dalgalari:\n                d[2] += 18.0\n                if d[2] < d[3]:\n                    oran = 1.0 - (d[2] / d[3])\n                    renk = tuple(int(c * oran) for c in MINT)\n                    cv2.circle(glow, (int(d[0]), int(d[1])), int(d[2]), renk, max(1, int(8 * oran)), cv2.LINE_AA)\n                    yeni_dalga.append(d)\n            sok_dalgalari = yeni_dalga\n\n            # Parçacıkları güncelle ve glow katmanına çiz\n            parcaciklar = [p for p in parcaciklar[-160:] if p.guncelle_ve_ciz(glow)]\n\n            # Gerçek Neon Bloom birleştirme!\n            img = bloom_birlestir(arka, glow)\n\n            # Üst HUD Paneli\n            panel(img, 12, 10, min(w - 12, 510), 74)\n            put_text(img, f\"SEIS NEON AR VFX  ·  Mod: {MODLAR[mod_idx]}  ·  FPS {fps.tick():.0f}\", (24, 16), 15, MINT)\n            put_text(img, aktif_efekt, (24, 42), 15, CREAM)\n\n            # Kalp şarj çubuğu\n            if kalp_sarj > 1:\n                bx1, by1, bx2, by2 = w - 210, 16, w - 16, 36\n                cv2.rectangle(img, (bx1, by1), (bx2, by2), PLUM_BG, -1)\n                cv2.rectangle(img, (bx1, by1), (bx1 + int((bx2 - bx1) * kalp_sarj / 100.0), by2), PINK, -1)\n                cv2.rectangle(img, (bx1, by1), (bx2, by2), MINT, 2)\n\n            if time.monotonic() < bildirim_bitis and bildirim:\n                put_text(img, bildirim, (w // 2 - 140, 88), 24, GOLD, bg=PLUM_BG)\n\n            status_line(\n                img,\n                \"Kalp | İki Açık El (Şimşek) | Tek Açık El | İşaret (Lazer) | V (SEIS) | Yumruk   (m: mod, s: foto, q: çıkış)\",\n                \"ok\" if result.hands else \"warn\",\n            )\n\n            key = loop.show(img)\n            if key == ord(\"m\"):\n                mod_idx = (mod_idx + 1) % len(MODLAR)\n            elif key == ord(\"c\"):\n                parcaciklar.clear()\n                lazer_izi.clear()\n                sok_dalgalari.clear()\n                kalp_sarj = 0.0\n            elif key == ord(\"s\"):\n                dosya = f\"seis_neon_vfx_{int(time.time())}.png\"\n                cv2.imwrite(dosya, img)\n                bildirim = f\"Kaydedildi: {dosya}\"\n                bildirim_bitis = time.monotonic() + 2.2\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "bonus4_cilt_ayna_studyo.py": "\"\"\"BONUS PROJE 4 — Işık Kamerayı Nasıl Yanıltır? (1. Çekim vs 2. Çekim Cilt Deneyi)\n\nAmaç (Çok Basit!):\n  Sosyal medyadaki veya uygulamalardaki 'yapay zekâ cilt analizi' araçlarının\n  sadece ışık açısı değiştiğinde nasıl farklı sonuçlar verdiğini canlı kanıtlamak!\n\nNasıl Yapılır?\n  1) Normal dururken [BOŞLUK] tuşuna bas -> 1. Çekim (Normal Işık) alınır.\n  2) Telefon fenerini yüzüne tut (veya pencereye dön) ve tekrar [BOŞLUK] bas -> 2. Çekim alınır.\n  3) Sağ ekranda aynı yüzün sadece ışık değişince nasıl bambaşka sayılar verdiğini gör!\n\nUyarı: Eğitim amaçlı görüntü analizidir; tıbbi tanı değildir.\n\nÇalıştırma : python bonus_projeler/bonus4_cilt_ayna_studyo.py\nTuşlar     : Boşluk: 1. / 2. Çekimi Al | 1-4: Harita Değiştir | r: Maske | c: Sıfırla | s: PNG Kaydet | q: Çıkış\n\"\"\"\n\nfrom __future__ import annotations\n\nimport sys\nimport time\nfrom pathlib import Path\n\nfor _p in Path(__file__).resolve().parents:\n    if (_p / \"src\").is_dir():\n        if str(_p / \"src\") not in sys.path:\n            sys.path.insert(0, str(_p / \"src\"))\n        break\n\nimport cv2\nimport numpy as np\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import put_text, status_line\nfrom common.fps import FPSMeter\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom face.tracker import FaceTracker\nfrom skin.analyzer import SkinAnalyzer, SkinReport\nfrom skin.metrics import compute_metrics, render_heatmap\nfrom skin.overlay import MAP_KEYS, disclaimer, draw_regions\nfrom skin.regions import build_region_masks\n\nPLUM_DARK = (18, 5, 28)\nPLUM_CARD = (34, 12, 50)\nMINT = (170, 232, 108)\nCREAM = (232, 240, 248)\nPEACH = (130, 175, 245)\nGOLD = (85, 215, 255)\nMUTED = (165, 155, 170)\n\nHARITA_ADLARI = {\n    MAP_KEYS[0]: \"1: Kızarıklık Haritası\",\n    MAP_KEYS[1]: \"2: Parlama Haritası\",\n    MAP_KEYS[2]: \"3: Doku / Pürüz Haritası\",\n    MAP_KEYS[3]: \"4: Renk Tonu Farkı\",\n}\n\nHELP_LINES = [\n    \"Amaç: Sadece ışık değiştiğinde kameranın cilt ölçümlerinin nasıl değiştiğini kanıtlamak.\",\n    \"• ADIM 1: Pencereye FARE İLE TIKLA (veya BOŞLUK bas) -> 1. Çekim (Normal Işık) alınır!\",\n    \"• ADIM 2: Telefon flaşını yüzüne tut / yan dön, tekrar TIKLA veya BOŞLUK bas -> 2. Çekim alınır!\",\n    \"• SONUÇ: Sağdaki tabloda aynı cildin iki ışıkta ne kadar farklı çıktığını karşılaştır!\",\n    \"• [1-4] Isı haritası seç  ·  [r] Bölge maskesi  ·  [c] Baştan başla  ·  [s] PNG kaydet\",\n]\n\n\ndef esnek_cekim_al(analyzer: SkinAnalyzer, frame, faces) -> SkinReport | None:\n    \"\"\"Kalite kapısına veya arkadaki yüzlere takılmadan en öndeki yüz için her zaman çekim üretir.\"\"\"\n    if not faces:\n        return None\n    ana_yuz = max(faces, key=lambda f: f.width_px)\n    rep = analyzer.analyze(frame.full_bgr, [ana_yuz], frame.scale_to_full)\n    if rep.metrics is not None:\n        return rep\n    # Yüz biraz uzak (ör. 140px) veya açı hafif eğik olsa bile eğitim deneyinde çekimi hesapla\n    if rep.crop is not None and rep.regions is not None:\n        valid = {k: m for k, m in rep.regions.masks.items() if int((m > 0).sum()) >= 20}\n        if valid:\n            rep.metrics = compute_metrics(rep.crop, valid)\n            return rep\n    return None\n\n\ndef harita_kucuk(report: SkinReport, map_name: str, max_w: int, max_h: int) -> np.ndarray:\n    m = report.metrics\n    heat = render_heatmap(report.crop, m.maps[map_name], m.union, map_name)\n    if config.MIRROR_DISPLAY:\n        heat = cv2.flip(heat, 1)\n    h, w = heat.shape[:2]\n    scale = min(max_w / max(w, 1), max_h / max(h, 1))\n    nw, nh = max(1, int(w * scale)), max(1, int(h * scale))\n    return cv2.resize(heat, (nw, nh), interpolation=cv2.INTER_LINEAR)\n\n\ndef ozet_degerler(report: SkinReport) -> dict[str, float]:\n    regs = report.metrics.regions\n    if not regs:\n        return {\"kizarik\": 0.0, \"parlama\": 0.0, \"doku\": 0.0, \"yanak_fark\": 0.0}\n    n = len(regs)\n    return {\n        \"kizarik\": sum(r.delta_a for r in regs.values()) / n,\n        \"parlama\": sum(r.shine_percent for r in regs.values()) / n,\n        \"doku\": sum(r.texture for r in regs.values()) / n,\n        \"yanak_fark\": report.metrics.cheek_delta_e or 0.0,\n    }\n\n\ndef sag_panel_ciz(\n    cekim_1: SkinReport | None,\n    cekim_2: SkinReport | None,\n    map_name: str,\n    height: int,\n    width: int = 470,\n) -> np.ndarray:\n    \"\"\"Yüksekliğe tam duyarlı, hiçbir satırı taşmayan sade Türkçe karşılaştırma paneli.\"\"\"\n    out = np.full((height, width, 3), PLUM_DARK, np.uint8)\n    cv2.line(out, (0, 0), (0, height), (80, 50, 95), 2)\n\n    # Üst başlık (sağ üstteki [F] Özellikler rozetine çarpmaması için solda hizalı)\n    cv2.rectangle(out, (2, 0), (width, 56), PLUM_CARD, -1)\n    cv2.line(out, (0, 56), (width, 56), MINT, 1)\n    put_text(out, \"IŞIK DENEYİ: 1. ÇEKİM vs 2. ÇEKİM\", (14, 9), 15, MINT)\n    put_text(out, HARITA_ADLARI.get(map_name, map_name) + \"  [1-4]\", (14, 33), 13, CREAM)\n\n    footer_y = height - 28\n\n    # Henüz hiç çekim alınmadıysa büyük ve çok net 2 adımlı rehber\n    if cekim_1 is None:\n        kutu_y = 74\n        cv2.rectangle(out, (14, kutu_y), (width - 14, kutu_y + 210), PLUM_CARD, -1)\n        cv2.rectangle(out, (14, kutu_y), (width - 14, kutu_y + 210), MINT, 1)\n        put_text(out, \"2 Adımda Işık Hilesini Gör:\", (28, kutu_y + 16), 17, GOLD)\n        put_text(out, \"ADIM 1:\", (28, kutu_y + 54), 14, MINT)\n        put_text(out, \"Ekrana FARE İLE TIKLA veya [BOŞLUK] bas.\", (104, kutu_y + 54), 14, CREAM)\n        put_text(out, \"ADIM 2:\", (28, kutu_y + 92), 14, PEACH)\n        put_text(out, \"Telefon ışığı tut / yan dön, tekrar TIKLA / BOŞLUK.\", (104, kutu_y + 92), 14, CREAM)\n        put_text(out, \"SONUÇ:\", (28, kutu_y + 132), 14, GOLD)\n        put_text(out, \"Cildin aynı olduğu halde kameranın nasıl\", (104, kutu_y + 132), 14, CREAM)\n        put_text(out, \"farklı sayılar ürettiğini yan yana gör!\", (104, kutu_y + 154), 14, CREAM)\n        put_text(out, \"[r] Bölge maskesi  ·  [s] PNG kaydet  ·  [F] Yardım\", (14, footer_y), 12, MUTED)\n        return out\n\n    # Dinamik görsel kutu yüksekliği (alt tabloya her zaman en az 185 px yer bırakır)\n    y_top = 66\n    avail_img_h = max(105, footer_y - y_top - 190)\n\n    if cekim_2 is None:\n        hm = harita_kucuk(cekim_1, map_name, width - 40, avail_img_h)\n        x0 = (width - hm.shape[1]) // 2\n        out[y_top:y_top + hm.shape[0], x0:x0 + hm.shape[1]] = hm\n        cv2.rectangle(out, (x0, y_top), (x0 + hm.shape[1], y_top + hm.shape[0]), MINT, 2)\n        y_tbl = y_top + hm.shape[0] + 12\n\n        cv2.rectangle(out, (14, y_tbl), (width - 14, footer_y - 10), PLUM_CARD, -1)\n        cv2.rectangle(out, (14, y_tbl), (width - 14, footer_y - 10), MINT, 1)\n        put_text(out, \"1. ÇEKİM ALINDI! Şimdi 2. Adım:\", (26, y_tbl + 12), 15, GOLD)\n        put_text(out, \"Yüzüne telefon feneri tut veya pencereye dönüp\", (26, y_tbl + 42), 13, CREAM)\n        put_text(out, \"tekrar [BOŞLUK] tuşuna bas -> karşılaştırma açılır!\", (26, y_tbl + 64), 13, MINT)\n        s1 = ozet_degerler(cekim_1)\n        put_text(\n            out,\n            f\"1. Çekim -> Kızarıklık:{s1['kizarik']:+.1f}  Parlama:%{s1['parlama']:.1f}  Doku:{s1['doku']:.1f}\",\n            (26, y_tbl + 100), 12, MUTED,\n        )\n    else:\n        slot_w = (width - 36) // 2\n        slot_h = avail_img_h\n        for idx, (lbl, rep, col) in enumerate([(\"1. ÇEKİM (Önce)\", cekim_1, MINT), (\"2. ÇEKİM (Yeni Işık)\", cekim_2, PEACH)]):\n            sx = 12 + idx * (slot_w + 12)\n            cv2.rectangle(out, (sx, y_top), (sx + slot_w, y_top + slot_h), PLUM_CARD, -1)\n            hm = harita_kucuk(rep, map_name, slot_w - 8, max(70, slot_h - 26))\n            ox = sx + (slot_w - hm.shape[1]) // 2\n            oy = y_top + 23\n            out[oy:oy + hm.shape[0], ox:ox + hm.shape[1]] = hm\n            put_text(out, lbl, (sx + 8, y_top + 4), 12, col)\n            cv2.rectangle(out, (sx, y_top), (sx + slot_w, y_top + slot_h), col, 1)\n\n        y_tbl = y_top + slot_h + 10\n        cv2.rectangle(out, (12, y_tbl), (width - 12, footer_y - 8), PLUM_CARD, -1)\n        cv2.rectangle(out, (12, y_tbl), (width - 12, footer_y - 8), (85, 50, 105), 1)\n\n        s1, s2 = ozet_degerler(cekim_1), ozet_degerler(cekim_2)\n        put_text(out, \"KARŞILAŞTIRMA TABLOSU\", (22, y_tbl + 7), 14, GOLD)\n        cols = [22, 218, 292, 372]\n        yy = y_tbl + 29\n        for cx, htxt in zip(cols, [\"Ölçülen Özellik\", \"1.Çekim\", \"2.Çekim\", \"Değişim\"]):\n            put_text(out, htxt, (cx, yy), 12, MUTED)\n\n        satirlar = [\n            (\"Kızarıklık tonu\", f\"{s1['kizarik']:+.1f}\", f\"{s2['kizarik']:+.1f}\", f\"{s2['kizarik'] - s1['kizarik']:+.1f}\"),\n            (\"Parlama oranı\", f\"%{s1['parlama']:.1f}\", f\"%{s2['parlama']:.1f}\", f\"{s2['parlama'] - s1['parlama']:+.1f}%\"),\n            (\"Cilt dokusu\", f\"{s1['doku']:.1f}\", f\"{s2['doku']:.1f}\", f\"{s2['doku'] - s1['doku']:+.1f}\"),\n            (\"Sağ-Sol yanak farkı\", f\"{s1['yanak_fark']:.1f}\", f\"{s2['yanak_fark']:.1f}\", f\"{s2['yanak_fark'] - s1['yanak_fark']:+.1f}\"),\n        ]\n        for ad, v1, v2, vf in satirlar:\n            yy += 21\n            if yy + 18 > footer_y - 24:\n                break\n            put_text(out, ad, (cols[0], yy), 12, CREAM)\n            put_text(out, v1, (cols[1], yy), 12, MINT)\n            put_text(out, v2, (cols[2], yy), 12, PEACH)\n            put_text(out, vf, (cols[3], yy), 12, GOLD)\n\n        if yy + 22 < footer_y - 6:\n            put_text(out, \"Sonuç: Cildin değişmedi, sadece ışık sayıları değiştirdi!\", (22, footer_y - 28), 12, GOLD)\n\n    put_text(out, \"[Boşluk] Yeni çekim  ·  [c] Sıfırla  ·  [s] PNG kaydet\", (14, footer_y), 12, MUTED)\n    return out\n\n\ndef main() -> None:\n    args = build_parser(\"Işık Kamerayı Nasıl Yanıltır? - 1. ve 2. Çekim Deneyi\").parse_args()\n    prepare, fps = FramePreparer(config.PROCESS_WIDTH), FPSMeter()\n    analyzer = SkinAnalyzer(use_segmenter=True)\n\n    cekim_1: SkinReport | None = None\n    cekim_2: SkinReport | None = None\n    map_name = MAP_KEYS[0]\n    show_regions = True\n    bildirim = \"\"\n    bildirim_bitis = 0.0\n\n    tiklandi = {\"tetik\": False}\n\n    def fare_tiklama(event, x, y, flags, param):\n        if event == cv2.EVENT_LBUTTONDOWN:\n            tiklandi[\"tetik\"] = True\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            FaceTracker() as faces, \\\n            DisplayLoop(\n                \"SEIS BONUS 4 - Isik Kamerayi Nasil Yaniltir?\",\n                args,\n                help_title=\"Bonus 4 · Işık Kamerayı Nasıl Yanıltır? (1. vs 2. Çekim)\",\n                help_lines=HELP_LINES,\n            ) as loop:\n        loop.on_mouse(fare_tiklama)\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            result = faces.process(frame)\n\n            # 860px genişlik -> ~484px yükseklik: sağ panelde hiçbir satır kesilmez!\n            canvas = Canvas(frame, width=860, mirror=not args.no_mirror)\n            if show_regions and result.faces:\n                face = max(result.faces, key=lambda f: f.width_px)\n                live_reg = build_region_masks(\n                    canvas.image, canvas.pts(face.points), face.width_px * canvas.scale,\n                    config.SKIN_ROI_EROSION_RATIO, None,\n                )\n                draw_regions(canvas.image, live_reg)\n            canvas.flip()\n            img = canvas.image\n            disclaimer(img)\n\n            # Sol üstte sade adım göstergesi (yüzü kapatmaz!)\n            adim_metni = (\n                \"ADIM 1: Ekrana TIKLA veya [BOŞLUK] bas -> 1. Çekimi al\"\n                if cekim_1 is None else\n                (\"ADIM 2: Işığı değiştirip TIKLA / [BOŞLUK] bas -> 2. Çekimi al\"\n                 if cekim_2 is None else\n                 \"TAMAMLANDI! Sağda 1. ve 2. çekim farkını incele\")\n            )\n            put_text(img, adim_metni, (14, 38), 15, MINT, bg=PLUM_DARK)\n            put_text(img, f\"FPS {fps.tick():.0f}\", (img.shape[1] - 86, 38), 14, CREAM, bg=PLUM_DARK)\n\n            if time.monotonic() < bildirim_bitis and bildirim:\n                put_text(img, bildirim, (14, img.shape[0] - 68), 15, GOLD, bg=PLUM_DARK)\n\n            alt_ipucu = (\n                \"[Sol Tık / Boşluk] Fotoğraf Çek  ·  [1-4] Harita  ·  [r] Maske  ·  [c] Sıfırla  ·  [s] Kaydet\"\n                if result.faces else \"Yüz bekleniyor — lütfen kameraya bakın.\"\n            )\n            status_line(img, alt_ipucu, \"ok\" if result.faces else \"warn\")\n\n            sag = sag_panel_ciz(cekim_1, cekim_2, map_name, height=img.shape[0], width=470)\n            birlesik = np.hstack([img, sag])\n            key = loop.show(birlesik)\n\n            cekim_iste = tiklandi[\"tetik\"] or key in (ord(\" \"), 13, 10)\n            tiklandi[\"tetik\"] = False\n\n            if cekim_iste:\n                yeni = esnek_cekim_al(analyzer, frame, result.faces)\n                if yeni is None:\n                    bildirim = \"Yüz algılanamadı! Kameraya bakıp tekrar tıkla / Boşluk bas.\"\n                elif cekim_1 is None:\n                    cekim_1 = yeni\n                    bildirim = \"1. Çekim alındı! Şimdi telefon ışığı tutup tekrar tıkla / Boşluk bas.\"\n                else:\n                    cekim_2 = yeni\n                    bildirim = \"2. Çekim alındı! Sağdaki değişim tablosuna bak!\"\n                bildirim_bitis = time.monotonic() + 3.0\n            elif ord(\"1\") <= key <= ord(\"4\"):\n                map_name = MAP_KEYS[key - ord(\"1\")]\n            elif key in (ord(\"r\"), ord(\"R\")):\n                show_regions = not show_regions\n            elif key in (ord(\"c\"), ord(\"C\")):\n                cekim_1 = cekim_2 = None\n                bildirim = \"Sıfırlandı — 1. Çekim için tekrar Boşluk bas.\"\n                bildirim_bitis = time.monotonic() + 2.0\n            elif key in (ord(\"s\"), ord(\"S\")):\n                dosya = f\"isik_deneyi_{int(time.time())}.png\"\n                cv2.imwrite(dosya, birlesik)\n                bildirim = f\"Rapor kaydedildi: {dosya}\"\n                bildirim_bitis = time.monotonic() + 2.4\n    analyzer.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "bonus5_sinif_enerji_olcer.py": "\"\"\"BONUS PROJE 5 — SEIS Sınıf Enerji & Gülümseme Ölçer (Gün Başı vs Eğitim Sonu)\n\nMevcut vision-workshop ortamındaki FaceTracker (max_faces=12, blendshapes=True)\nile çalışır; ek kütüphane veya yeni model gerektirmez.\n\nNasıl Çalışır?\n  - Kameradaki tüm yüzleri (aynı anda 12 yüze kadar) gerçek zamanlı yakalar.\n  - MediaPipe blendshape mimik katsayılarından (mouthSmileLeft/Right, cheekSquintLeft/Right)\n    her yüzün canlı gülümseme / enerji skorunu (%0–%100) hesaplar.\n  - 1 tuşu: GÜN BAŞI (16:00) sınıf enerjisini kaydeder.\n  - 2 tuşu: EĞİTİM SONU (20:00) sınıf enerjisini kaydeder ve +Δ% artışı yan yana gösterir!\n  - s tuşu: SEIS Instagram / hatıra için karşılaştırma raporunu PNG kaydeder.\n\nNot: Yüz ifadesi (gülümseme/mimik) hareket sinyali ölçümüdür; psikolojik tanı değildir.\n\nÇalıştırma : python bonus_projeler/bonus5_sinif_enerji_olcer.py\nTuşlar     : 1: Gün Başı Kaydet  |  2: Eğitim Sonu Kaydet  |  s: PNG Kaydet  |  c: Sıfırla  |  q: Çıkış\n\"\"\"\n\nimport sys\nimport time\nfrom pathlib import Path\n\nimport cv2\nimport numpy as np\n\n# src klasörünü otomatik bul (hem atolye-baslangic/bonus_projeler hem Gemini/bonus_projeler için)\nfor _p in Path(__file__).resolve().parents:\n    if (_p / \"src\").is_dir():\n        if str(_p / \"src\") not in sys.path:\n            sys.path.insert(0, str(_p / \"src\"))\n        break\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import put_text, status_line\nfrom common.fps import FPSMeter\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom face.tracker import FaceTracker\n\n# SEIS Afiş Paleti (BGR)\nPLUM_DARK = (18, 5, 28)\nPLUM_CARD = (32, 10, 48)\nMINT = (170, 232, 108)\nCREAM = (218, 236, 247)\nPEACH = (130, 161, 235)\nGOLD = (85, 215, 255)\nMUTED = (145, 132, 148)\n\n\ndef yuz_enerji_skoru(bs: dict[str, float]) -> float:\n    \"\"\"Blendshape mimik katsayılarından 0..100 arası canlı gülümseme/enerji skoru üretir.\"\"\"\n    if not bs:\n        return 35.0\n    gulumseme = (bs.get(\"mouthSmileLeft\", 0.0) + bs.get(\"mouthSmileRight\", 0.0)) / 2.0\n    yanak = (bs.get(\"cheekSquintLeft\", 0.0) + bs.get(\"cheekSquintRight\", 0.0)) / 2.0\n    kas_catik = (bs.get(\"browDownLeft\", 0.0) + bs.get(\"browDownRight\", 0.0)) / 2.0\n    # Nötr ifade ~%35, güçlü gülümseme %95-100 bandına çıkar\n    ham = 0.35 + 0.68 * gulumseme + 0.15 * yanak - 0.18 * kas_catik\n    return float(max(5.0, min(100.0, ham * 100.0)))\n\n\ndef enerji_rengi(skor: float) -> tuple[int, int, int]:\n    if skor >= 72:\n        return MINT\n    if skor >= 50:\n        return GOLD\n    return PEACH\n\n\ndef enerji_etiketi(skor: float) -> str:\n    if skor >= 78:\n        return \"Çok Yüksek!\"\n    if skor >= 60:\n        return \"Pozitif\"\n    if skor >= 42:\n        return \"Odaklanmış\"\n    return \"Düşük / Yorgun\"\n\n\ndef bar_ciz(img: np.ndarray, x: int, y: int, w: int, h: int, yuzde: float, renk):\n    cv2.rectangle(img, (x, y), (x + w, y + h), (26, 8, 38), -1)\n    dolu = int(w * max(0.0, min(100.0, yuzde)) / 100.0)\n    if dolu > 0:\n        cv2.rectangle(img, (x, y), (x + dolu, y + h), renk, -1)\n    cv2.rectangle(img, (x, y), (x + w, y + h), (90, 60, 110), 1)\n\n\ndef sag_panel_ciz(\n    anlik_skor: float,\n    anlik_kisi: int,\n    gun_basi: dict | None,\n    egitim_sonu: dict | None,\n    height: int,\n    width: int = 410,\n) -> np.ndarray:\n    \"\"\"Sağ tarafta SEIS Sınıf Enerji Karşılaştırma Paneli çizer.\"\"\"\n    out = np.full((height, width, 3), PLUM_DARK, np.uint8)\n    cv2.rectangle(out, (0, 0), (width, 56), PLUM_CARD, -1)\n    cv2.line(out, (0, 56), (width, 56), MINT, 1)\n    put_text(out, \"SEIS SINIF ENERJİ ÖLÇER\", (16, 10), 17, MINT)\n    put_text(out, \"Gün Başı vs Eğitim Sonu Karşılaştırma\", (16, 33), 12, CREAM)\n\n    # 1. Anlık Canlı Kart\n    cv2.rectangle(out, (14, 70), (width - 14, 178), PLUM_CARD, -1)\n    cv2.rectangle(out, (14, 70), (width - 14, 178), MINT, 1)\n    put_text(out, f\"CANLI SINIF ENERJİSİ ({anlik_kisi} yüz)\", (24, 78), 13, MINT)\n    renk = enerji_rengi(anlik_skor)\n    put_text(out, f\"%{anlik_skor:.0f}\", (24, 102), 34, renk)\n    put_text(out, enerji_etiketi(anlik_skor), (124, 116), 16, CREAM)\n    bar_ciz(out, 24, 150, width - 48, 16, anlik_skor, renk)\n\n    # 2. Gün Başı (16:00) Kaydı\n    cv2.rectangle(out, (14, 192), (width - 14, 280), PLUM_CARD, -1)\n    put_text(out, \"1 · GÜN BAŞI ÖLÇÜMÜ (16:00)\", (24, 200), 13, GOLD)\n    if gun_basi:\n        put_text(out, f\"%{gun_basi['skor']:.1f}  ({gun_basi['kisi']} yüz · {gun_basi['saat']})\", (24, 224), 16, CREAM)\n        bar_ciz(out, 24, 254, width - 48, 14, gun_basi[\"skor\"], GOLD)\n    else:\n        put_text(out, \"Kaydetmek için [1] tuşuna bas\", (24, 232), 14, MUTED)\n\n    # 3. Eğitim Sonu (20:00) Kaydı\n    cv2.rectangle(out, (14, 294), (width - 14, 382), PLUM_CARD, -1)\n    put_text(out, \"2 · EĞİTİM SONU ÖLÇÜMÜ (20:00)\", (24, 302), 13, MINT)\n    if egitim_sonu:\n        put_text(out, f\"%{egitim_sonu['skor']:.1f}  ({egitim_sonu['kisi']} yüz · {egitim_sonu['saat']})\", (24, 326), 16, CREAM)\n        bar_ciz(out, 24, 356, width - 48, 14, egitim_sonu[\"skor\"], MINT)\n    else:\n        put_text(out, \"Kaydetmek için [2] tuşuna bas\", (24, 334), 14, MUTED)\n\n    # 4. Fark / Sonuç Kartı\n    y_res = 396\n    if y_res + 74 < height:\n        cv2.rectangle(out, (14, y_res), (width - 14, height - 34), (24, 48, 38) if (gun_basi and egitim_sonu) else PLUM_CARD, -1)\n        if gun_basi and egitim_sonu:\n            fark = egitim_sonu[\"skor\"] - gun_basi[\"skor\"]\n            isaret = \"+\" if fark >= 0 else \"\"\n            put_text(out, f\"ENERJİ DEĞİŞİMİ: {isaret}%{fark:.1f}\", (24, y_res + 12), 18, MINT if fark >= 0 else PEACH)\n            put_text(out, \"Harika bir SEIS OpenCV Atölyesi!\", (24, y_res + 42), 13, CREAM)\n        else:\n            put_text(out, \"1 ve 2 kaydedilince artış burada görünür.\", (24, y_res + 20), 13, MUTED)\n\n    put_text(out, \"Mimik hareket sinyali ölçümüdür (eğitim demosu).\", (14, height - 24), 11, MUTED)\n    return out\n\n\ndef main():\n    args = build_parser(\"SEIS Sınıf Enerji & Gülümseme Ölçer\").parse_args()\n    prepare, fps = FramePreparer(config.PROCESS_WIDTH), FPSMeter()\n\n    gun_basi = None\n    egitim_sonu = None\n    smooth_skor = 50.0\n    bildirim = \"\"\n    bildirim_bitis = 0.0\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            FaceTracker(max_faces=12, blendshapes=True) as faces, \\\n            DisplayLoop(\n                \"SEIS Sinif Enerji Olcer\",\n                args,\n                help_title=\"Bonus 5 · SEIS Sınıf Enerji & Mutluluk Ölçer\",\n                help_lines=[\n                    \"Amaç: Sınıftaki 12 yüze kadar gülümseme/canlılık skorunu Gün Başı vs Eğitim Sonu kıyaslamak.\",\n                    \"• [1] Gün Başı (16:00) sınıf ortalama enerjisini ve kişi sayısını kaydeder.\",\n                    \"• [2] Eğitim Sonu (20:00) ölçümünü alır ve +Δ% değişim tablosunu gösterir.\",\n                    \"• [s] Karşılaştırma raporunu PNG kaydet  ·  [c] Kayıtları sıfırla  ·  [F] Kapat.\",\n                ],\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            result = faces.process(frame)\n\n            canvas = Canvas(frame, width=720, mirror=not args.no_mirror)\n            skorlar = []\n            etiketler = []\n\n            for face in result.faces:\n                skor = yuz_enerji_skoru(face.blendshapes)\n                skorlar.append(skor)\n                renk = enerji_rengi(skor)\n                bx = canvas.pts(face.box)\n                x1, y1, x2, y2 = int(bx[0]), int(bx[1]), int(bx[2]), int(bx[3])\n                cv2.rectangle(canvas.image, (x1, y1), (x2, y2), renk, 2, cv2.LINE_AA)\n                etiketler.append((face.box, skor, renk))\n\n            canvas.flip()\n            img = canvas.image\n\n            for box, skor, renk in etiketler:\n                px, py = canvas.screen((box[2] if canvas.mirror else box[0], box[1]))\n                put_text(img, f\"%{skor:.0f}\", (int(px), max(10, int(py) - 24)), 15, renk, bg=PLUM_DARK)\n\n            anlik = sum(skorlar) / len(skorlar) if skorlar else 0.0\n            if skorlar:\n                smooth_skor = 0.25 * anlik + 0.75 * smooth_skor\n            goster_skor = smooth_skor if skorlar else 0.0\n\n            put_text(img, f\"Algılanan Yüz: {len(skorlar)}  ·  FPS {fps.tick():.0f}\", (14, 12), 15, MINT, bg=PLUM_DARK)\n            if time.monotonic() < bildirim_bitis and bildirim:\n                put_text(img, bildirim, (14, img.shape[0] - 66), 16, GOLD, bg=PLUM_DARK)\n\n            status_line(\n                img,\n                \"[1] Gün Başı Kaydet  |  [2] Eğitim Sonu Kaydet  |  [s] PNG Rapor  |  [c] Sıfırla  |  [q] Çıkış\",\n                \"ok\" if skorlar else \"warn\",\n            )\n\n            sag = sag_panel_ciz(goster_skor, len(skorlar), gun_basi, egitim_sonu, height=img.shape[0])\n            birlesik = np.hstack([img, sag])\n            key = loop.show(birlesik)\n\n            if key == ord(\"1\") and skorlar:\n                gun_basi = {\"skor\": goster_skor, \"kisi\": len(skorlar), \"saat\": time.strftime(\"%H:%M\")}\n                bildirim = f\"✓ Gün Başı kaydedildi: %{goster_skor:.1f} ({len(skorlar)} yüz)\"\n                bildirim_bitis = time.monotonic() + 2.6\n            elif key == ord(\"2\") and skorlar:\n                egitim_sonu = {\"skor\": goster_skor, \"kisi\": len(skorlar), \"saat\": time.strftime(\"%H:%M\")}\n                bildirim = f\"✓ Eğitim Sonu kaydedildi: %{goster_skor:.1f} ({len(skorlar)} yüz)\"\n                bildirim_bitis = time.monotonic() + 2.6\n            elif key == ord(\"c\"):\n                gun_basi = egitim_sonu = None\n                bildirim = \"Ölçümler sıfırlandı.\"\n                bildirim_bitis = time.monotonic() + 1.8\n            elif key == ord(\"s\"):\n                dosya = f\"seis_sinif_enerji_{int(time.time())}.png\"\n                cv2.imwrite(dosya, birlesik)\n                bildirim = f\"📸 Kaydedildi: {dosya}\"\n                bildirim_bitis = time.monotonic() + 2.5\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "bonus6_goz_flappy_oyunu.py": "\"\"\"BONUS PROJE 6 — SEIS Neon Flappy Oyunu (Göz Kırpma / Ağız Açma / Kafa Kontrolü)\n\nEk kütüphane (pyautogui vb.) gerektirmez — tamamen OpenCV + MediaPipe ile çalışır!\n3 farklı temassız kontrol modu arasında 'm' tuşuyla anında geçiş yapabilirsiniz:\n  1) KAFA MODU (Varsayılan · En Kolay): Başını yukarı/aşağı oynat -> kuş burnunu takip eder!\n  2) GÖZ KIRPMA (EAR): Gözünü her kırptığında kuş zıplar!\n  3) AĞIZ AÇMA (MAR): Ağzını açınca kuş zıplar!\n\nÇalıştırma : python bonus_projeler/bonus6_goz_flappy_oyunu.py\nTuşlar     : m: Kontrol modu değiştir | Boşluk / r: Yeniden başlat | f: Özellikler | q: Çıkış\n\"\"\"\n\nfrom __future__ import annotations\n\nimport random\nimport sys\nimport time\nfrom pathlib import Path\n\nfor _p in Path(__file__).resolve().parents:\n    if (_p / \"src\").is_dir():\n        sys.path.insert(0, str(_p / \"src\"))\n        break\n\nimport cv2\nimport numpy as np\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import AMBER, GRAY, INK, RED, TEAL, WHITE, panel, put_text, status_line\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom face.metrics import LEFT_EYE_EAR, RIGHT_EYE_EAR, BlinkDetector, eye_aspect_ratio, mouth_aspect_ratio\nfrom face.tracker import FaceTracker\n\nMODLAR = [\"KAFA (Burun Takibi)\", \"GÖZ KIRPMA (EAR)\", \"AĞIZ AÇMA (MAR)\"]\n\nHELP_LINES = [\n    \"Amaç: Yüz hareketlerinle (kafa, göz kırpma veya ağız açma) neon Flappy oyununu temassız oynamak!\",\n    \"• [m] Kontrol modunu değiştirir: 1) Kafa (en kolay)  2) Göz Kırpma (EAR)  3) Ağız Açma (MAR).\",\n    \"• [Boşluk / r] Oyun bittiğinde anında yeniden başlatır · En yüksek skor otomatik tutulur!\",\n    \"• İpucu: Tarayıcıdaki Chrome Dino için aynı EAR/MAR tetiklemesine pyautogui.press('space') bağlanabilir.\",\n    \"• [F] Bu rehberi aç/kapat  ·  [Q / Esc] Çıkış.\",\n]\n\n\ndef boru_uret(w: int, h: int, aralik: int = 168) -> dict:\n    ust_h = random.randint(75, max(95, h - aralik - 115))\n    return {\"x\": float(w + 40), \"ust\": ust_h, \"aralik\": aralik, \"gecti\": False}\n\n\ndef main() -> None:\n    args = build_parser(\"SEIS Neon Flappy - Göz/Ağız/Kafa Oyunu\").parse_args()\n    prepare = FramePreparer(config.PROCESS_WIDTH)\n    blink = BlinkDetector()\n\n    mod_idx = 0\n    skor = 0\n    rekor = 0\n    oyun_bitti = False\n    basladi = False\n\n    kus_y = 240.0\n    kus_vy = 0.0\n    borular: list[dict] = []\n    son_agiz_acik = False\n    son_blink = 0\n    son_zaman = time.perf_counter()\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            FaceTracker(max_faces=1) as faces, \\\n            DisplayLoop(\n                \"SEIS BONUS 6 - Neon Flappy (Goz / Agiz / Kafa)\",\n                args,\n                help_title=\"Bonus 6 · SEIS Neon Flappy (Göz / Ağız / Kafa Kontrolü)\",\n                help_lines=HELP_LINES,\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            result = faces.process(frame)\n            canvas = Canvas(frame, width=920, mirror=not args.no_mirror)\n            canvas.flip()\n            img = canvas.image\n            h, w = img.shape[:2]\n\n            # Oyun arka planını hafifçe karart ki neon borular ve kuş net parlasın\n            cv2.convertScaleAbs(img, alpha=0.58, beta=0, dst=img)\n\n            now = time.perf_counter()\n            dt = min(0.05, now - son_zaman)\n            son_zaman = now\n\n            kus_x = int(w * 0.24)\n            kus_r = 18\n            ear = 0.0\n            mar = 0.0\n            zipla = False\n\n            if result.faces:\n                face = result.faces[0]\n                p = face.points\n                ear = (eye_aspect_ratio(p, RIGHT_EYE_EAR) + eye_aspect_ratio(p, LEFT_EYE_EAR)) / 2.0\n                blink.update(ear)\n                mar = mouth_aspect_ratio(p)\n\n                # Mod 0: Kafa (Burun noktası 1) — en kolay ve akıcı mod\n                if mod_idx == 0:\n                    _, burun_y = canvas.screen(p[1])\n                    hedef_y = float(np.clip((burun_y - h * 0.22) / max(h * 0.56, 1.0) * (h - 90) + 45, 45, h - 60))\n                    kus_y += (hedef_y - kus_y) * 0.28\n                    if not basladi and not oyun_bitti:\n                        basladi = True\n                # Mod 1: Göz kırpma (EAR)\n                elif mod_idx == 1:\n                    if blink.blinks > son_blink:\n                        son_blink = blink.blinks\n                        zipla = True\n                # Mod 2: Ağız açma (MAR)\n                elif mod_idx == 2:\n                    agiz_acik = mar > max(0.32, config.MOUTH_OPEN_MAR * 0.85)\n                    if agiz_acik and not son_agiz_acik:\n                        zipla = True\n                    son_agiz_acik = agiz_acik\n\n            if zipla:\n                if oyun_bitti:\n                    borular.clear()\n                    skor = 0\n                    kus_y = h * 0.45\n                    kus_vy = -310.0\n                    oyun_bitti = False\n                    basladi = True\n                else:\n                    basladi = True\n                    kus_vy = -310.0\n\n            # Fizik ve boru hareketi\n            if basladi and not oyun_bitti:\n                if mod_idx != 0:\n                    kus_vy += 860.0 * dt\n                    kus_y += kus_vy * dt\n                if not borular or borular[-1][\"x\"] < w - 300:\n                    borular.append(boru_uret(w, h, aralik=max(150, int(h * 0.34))))\n                hiz = 185.0 + min(130.0, skor * 6.0)\n                for b in borular:\n                    b[\"x\"] -= hiz * dt\n                    if not b[\"gecti\"] and b[\"x\"] + 58 < kus_x:\n                        b[\"gecti\"] = True\n                        skor += 1\n                        rekor = max(rekor, skor)\n                borular = [b for b in borular if b[\"x\"] > -80]\n\n                # Çarpışma kontrolü\n                if kus_y - kus_r < 34 or kus_y + kus_r > h - 38:\n                    oyun_bitti = True\n                for b in borular:\n                    bx1, bx2 = int(b[\"x\"]), int(b[\"x\"] + 58)\n                    if bx1 - kus_r < kus_x < bx2 + kus_r:\n                        if kus_y - kus_r < b[\"ust\"] or kus_y + kus_r > b[\"ust\"] + b[\"aralik\"]:\n                            oyun_bitti = True\n\n            # Neon boruları çiz\n            for b in borular:\n                bx1, bx2 = int(b[\"x\"]), int(b[\"x\"] + 58)\n                ust = int(b[\"ust\"])\n                alt = int(b[\"ust\"] + b[\"aralik\"])\n                cv2.rectangle(img, (bx1, 34), (bx2, ust), (90, 210, 120), -1)\n                cv2.rectangle(img, (bx1, 34), (bx2, ust), (180, 255, 200), 2)\n                cv2.rectangle(img, (bx1, alt), (bx2, h - 38), (90, 210, 120), -1)\n                cv2.rectangle(img, (bx1, alt), (bx2, h - 38), (180, 255, 200), 2)\n\n            # Neon SEIS kuşunu çiz\n            ky = int(np.clip(kus_y, 40, h - 46))\n            cv2.circle(img, (kus_x, ky), kus_r + 6, (90, 220, 255), 2, cv2.LINE_AA)\n            cv2.circle(img, (kus_x, ky), kus_r, (40, 210, 255), -1, cv2.LINE_AA)\n            cv2.circle(img, (kus_x + 7, ky - 5), 5, WHITE, -1, cv2.LINE_AA)\n            cv2.circle(img, (kus_x + 9, ky - 5), 2, INK, -1, cv2.LINE_AA)\n            cv2.polylines(img, [np.array([[kus_x + 16, ky - 2], [kus_x + 28, ky + 2], [kus_x + 16, ky + 7]])],\n                          True, AMBER, 2, cv2.LINE_AA)\n\n            # Üst skor & mod paneli\n            panel(img, 0, 0, w, 40, alpha=0.82)\n            put_text(img, f\"SKOR: {skor}   REKOR: {rekor}   ·   Mod: {MODLAR[mod_idx]} [m]\",\n                     (14, 10), 16, TEAL)\n            put_text(img, f\"EAR:{ear:.2f}  MAR:{mar:.2f}\", (w - 300, 11), 13, GRAY)\n\n            if not basladi and not oyun_bitti:\n                panel(img, w // 2 - 220, h // 2 - 44, w // 2 + 220, h // 2 + 44, alpha=0.85)\n                put_text(img, \"Başlamak için göz kırp / ağzını aç / Boşluk bas!\",\n                         (w // 2 - 200, h // 2 - 14), 15, WHITE)\n            elif oyun_bitti:\n                panel(img, w // 2 - 190, h // 2 - 58, w // 2 + 190, h // 2 + 58, alpha=0.88)\n                cv2.rectangle(img, (w // 2 - 190, h // 2 - 58), (w // 2 + 190, h // 2 + 58), RED, 2)\n                put_text(img, f\"OYUN BİTTİ!   Skor: {skor}  (Rekor: {rekor})\", (w // 2 - 165, h // 2 - 36), 17, AMBER)\n                put_text(img, \"Tekrar oynamak için [Boşluk] veya [r] tuşuna bas\", (w // 2 - 170, h // 2 + 6), 14, WHITE)\n\n            status_line(img, \"[m] Mod değiştir (Kafa / Göz / Ağız)  ·  [r] Yeniden başlat  ·  [F] Özellikler\",\n                        \"ok\" if result.faces else \"warn\")\n\n            key = loop.show(img)\n            if key in (ord(\"m\"), ord(\"M\")):\n                mod_idx = (mod_idx + 1) % len(MODLAR)\n                kus_vy = 0.0\n                son_blink = blink.blinks\n            elif key in (ord(\" \"), ord(\"r\"), ord(\"R\")):\n                borular.clear()\n                skor = 0\n                kus_y = h * 0.45\n                kus_vy = -260.0 if mod_idx != 0 else 0.0\n                oyun_bitti = False\n                basladi = True\n                son_blink = blink.blinks\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n",
  "bonus7_tas_kagit_makas.py": "\"\"\"BONUS PROJE 7 — Yapay Zekâya Karşı Taş–Kağıt–Makas (21 El Eklem Noktası)\n\nKameraya gösterdiğiniz el işaretini parmak açılarına göre anlık tanır:\n  • ✊ TAŞ   : 0 veya 1 açık parmak (yumruk)\n  • ✌️ MAKAS : İşaret + orta parmak açık, yüzük + serçe kapalı\n  • 🖐️ KAĞIT : 4 veya 5 açık parmak (açık el)\n\nÇalıştırma : python bonus_projeler/bonus7_tas_kagit_makas.py\nTuşlar     : Boşluk: Yeni Tur (3-2-1 geri sayım) | c: Skoru sıfırla | f: Özellikler | q: Çıkış\n\"\"\"\n\nfrom __future__ import annotations\n\nimport random\nimport sys\nimport time\nfrom pathlib import Path\n\nfor _p in Path(__file__).resolve().parents:\n    if (_p / \"src\").is_dir():\n        sys.path.insert(0, str(_p / \"src\"))\n        break\n\nimport cv2\nimport numpy as np\n\nimport config\nfrom camera import Camera, CameraError\nfrom common.app import Canvas, DisplayLoop, build_parser\nfrom common.draw import AMBER, BLUE, GRAY, INK, RED, TEAL, WHITE, panel, put_text, status_line\nfrom common.frame import FramePreparer\nfrom common.models import ModelMissingError\nfrom hands.gestures import finger_states\nfrom hands.overlay import draw_hand\nfrom hands.tracker import HandTracker\n\nHAMLELER = [\"TAŞ\", \"KAĞIT\", \"MAKAS\"]\nKAZANAN = {(\"TAŞ\", \"MAKAS\"), (\"KAĞIT\", \"TAŞ\"), (\"MAKAS\", \"KAĞIT\")}\n\nHELP_LINES = [\n    \"Amaç: 21 el eklem noktasından parmak durumlarını okuyarak bilgisayara karşı Taş–Kağıt–Makas oynamak.\",\n    \"• ✊ TAŞ (yumruk)  ·  ✌️ MAKAS (işaret+orta açık)  ·  🖐️ KAĞIT (4-5 parmak açık).\",\n    \"• [Boşluk / Space] 3-2-1 geri sayımını başlatır; süre bitince elindeki hamle okunur!\",\n    \"• [c] Skor tablosunu ve galibiyet serisini sıfırlar.\",\n    \"• [F] Bu rehberi aç/kapat  ·  [Q / Esc] Çıkış.\",\n]\n\n\ndef hamle_tani(points) -> str | None:\n    \"\"\"Parmak açık/kapalı durumlarından TAŞ, KAĞIT veya MAKAS döndürür.\"\"\"\n    st = finger_states(points)\n    acik = sum(1 for v in st.values() if v is True)\n    if acik <= 1:\n        return \"TAŞ\"\n    if acik >= 4:\n        return \"KAĞIT\"\n    if st.get(\"işaret\") is True and st.get(\"orta\") is True and st.get(\"yüzük\") is False and st.get(\"serçe\") is False:\n        return \"MAKAS\"\n    return None\n\n\ndef main() -> None:\n    args = build_parser(\"Taş-Kağıt-Makas (AI vs Sen)\").parse_args()\n    prepare = FramePreparer(config.PROCESS_WIDTH)\n\n    sen_skor = 0\n    ai_skor = 0\n    berabere = 0\n    seri = 0\n\n    geri_sayim_bitis: float | None = None\n    son_sen: str | None = None\n    son_ai: str | None = None\n    son_sonuc = \"Başlamak için [Boşluk] tuşuna bas!\"\n    son_renk = TEAL\n\n    with Camera(args.source, config.CAPTURE_WIDTH, config.CAPTURE_HEIGHT) as cam, \\\n            HandTracker(max_hands=1) as hands, \\\n            DisplayLoop(\n                \"SEIS BONUS 7 - Tas Kagit Makas (AI vs Sen)\",\n                args,\n                help_title=\"Bonus 7 · Yapay Zekâya Karşı Taş–Kağıt–Makas\",\n                help_lines=HELP_LINES,\n            ) as loop:\n        while loop.running:\n            raw = cam.read()\n            if raw is None:\n                break\n            frame = prepare(raw)\n            result = hands.process(frame)\n            canvas = Canvas(frame, width=920, mirror=not args.no_mirror)\n\n            hand = result.hands[0] if result.hands else None\n            anlik_hamle = hamle_tani(hand.points) if hand else None\n            if hand:\n                draw_hand(canvas.image, canvas.pts(hand.points))\n\n            canvas.flip()\n            img = canvas.image\n            h, w = img.shape[:2]\n\n            # Geri sayım kontrolü\n            now = time.monotonic()\n            if geri_sayim_bitis is not None:\n                kalan = geri_sayim_bitis - now\n                if kalan > 0:\n                    sayi = int(np.ceil(kalan))\n                    cx, cy = w // 2, h // 2 - 20\n                    panel(img, cx - 95, cy - 68, cx + 95, cy + 68, alpha=0.82)\n                    cv2.circle(img, (cx, cy), 56, TEAL, 3, cv2.LINE_AA)\n                    put_text(img, str(sayi), (cx - 18, cy - 32), 54, AMBER)\n                    put_text(img, \"HAMLE HAZIRLA!\", (cx - 72, cy + 40), 14, WHITE)\n                else:\n                    geri_sayim_bitis = None\n                    if anlik_hamle is None:\n                        son_sen, son_ai = \"ALGILANMADI\", \"-\"\n                        son_sonuc = \"El görünmedi! Tekrar [Boşluk] bas.\"\n                        son_renk = AMBER\n                    else:\n                        son_sen = anlik_hamle\n                        son_ai = random.choice(HAMLELER)\n                        if son_sen == son_ai:\n                            berabere += 1\n                            son_sonuc = f\"BERABERE! ({son_sen} = {son_ai})\"\n                            son_renk = BLUE\n                        elif (son_sen, son_ai) in KAZANAN:\n                            sen_skor += 1\n                            seri += 1\n                            son_sonuc = f\"KAZANDIN! ({son_sen} > {son_ai})\"\n                            son_renk = TEAL\n                        else:\n                            ai_skor += 1\n                            seri = 0\n                            son_sonuc = f\"BİLGİSAYAR KAZANDI! ({son_ai} > {son_sen})\"\n                            son_renk = RED\n\n            # Üst skor tabelası\n            panel(img, 0, 0, w, 46, alpha=0.84)\n            put_text(img, f\"SEN {sen_skor}  :  {ai_skor} BİLGİSAYAR   (Berabere: {berabere} · Seri: {seri})\",\n                     (16, 12), 17, WHITE)\n\n            # Sol alt: Anlık algılanan el hamlesi\n            panel(img, 14, 58, 280, 146, alpha=0.78)\n            put_text(img, \"Canlı El Algılama\", (26, 66), 14, GRAY)\n            put_text(img, anlik_hamle or \"El bekleniyor...\", (26, 94), 24, TEAL if anlik_hamle else AMBER)\n\n            # Sağ alt: Son tur sonucu\n            panel(img, w - 340, 58, w - 14, 176, alpha=0.80)\n            put_text(img, \"Son Tur Sonucu\", (w - 326, 66), 14, GRAY)\n            put_text(img, f\"Sen: {son_sen or '-'}   vs   AI: {son_ai or '-'}\", (w - 326, 94), 17, WHITE)\n            put_text(img, son_sonuc, (w - 326, 128), 15, son_renk)\n\n            status_line(img, \"[Boşluk] Yeni Tur Başlat (3-2-1)  ·  [c] Skoru Sıfırla  ·  [F] Özellikler\",\n                        \"ok\" if hand else \"warn\")\n\n            key = loop.show(img)\n            if key == ord(\" \") and geri_sayim_bitis is None:\n                geri_sayim_bitis = time.monotonic() + 2.6\n            elif key in (ord(\"c\"), ord(\"C\")):\n                sen_skor = ai_skor = berabere = seri = 0\n                son_sen = son_ai = None\n                son_sonuc = \"Skor sıfırlandı! [Boşluk] ile başla.\"\n                son_renk = TEAL\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (CameraError, ModelMissingError) as exc:\n        print(exc)\n"
};
